var TRIVIA_BANK=[{"q":"What date is inscribed in the Bitcoin genesis block?","options":["January 3, 2009","October 31, 2008","January 9, 2009","November 1, 2008"],"answer":0,"explanation":"The genesis block (Block 0) was mined on January 3, 2009, and contains a Times headline from that date."},{"q":"What newspaper headline did Satoshi embed in the genesis block?","options":["Global financial crisis deepens","Chancellor on brink of second bailout for banks","Banks receive government lifeline","Federal Reserve cuts rates to zero"],"answer":1,"explanation":"Satoshi embedded 'The Times 03/Jan/2009 Chancellor on brink of second bailout for banks' as a timestamp proof and political statement."},{"q":"When was the Bitcoin whitepaper published?","options":["November 1, 2008","January 3, 2009","October 31, 2008","August 18, 2008"],"answer":2,"explanation":"Satoshi Nakamoto published 'Bitcoin: A Peer-to-Peer Electronic Cash System' on October 31, 2008, via the cryptography mailing list."},{"q":"Who received the first ever Bitcoin transaction from Satoshi Nakamoto?","options":["Adam Back","Nick Szabo","Wei Dai","Hal Finney"],"answer":3,"explanation":"Hal Finney received 10 BTC from Satoshi in block 170 on January 12, 2009, making it the first known person-to-person Bitcoin transaction."},{"q":"How many bitcoins were paid for two pizzas on Bitcoin Pizza Day (May 22, 2010)?","options":["10,000 BTC","1,000 BTC","50,000 BTC","5,000 BTC"],"answer":0,"explanation":"Laszlo Hanyecz paid 10,000 BTC for two Papa John's pizzas, marking the first known real-world Bitcoin transaction."},{"q":"Which Bitcoin exchange suffered a major hack in 2014, losing approximately 850,000 BTC?","options":["Bitfinex","Mt. Gox","BTC-e","Bitstamp"],"answer":1,"explanation":"Mt. Gox, once handling over 70% of all Bitcoin transactions, filed for bankruptcy in February 2014 after losing roughly 850,000 BTC."},{"q":"What was the name of the online marketplace that popularized Bitcoin for illicit transactions, shut down by the FBI in 2013?","options":["Agora","AlphaBay","Silk Road","Evolution"],"answer":2,"explanation":"Silk Road, operated by Ross Ulbricht (Dread Pirate Roberts), was seized by the FBI in October 2013 and demonstrated Bitcoin's use as censorship-resistant money."},{"q":"In what year did the Bitcoin block reward first halve from 50 BTC to 25 BTC?","options":["2014","2013","2011","2012"],"answer":3,"explanation":"The first Bitcoin halving occurred on November 28, 2012, at block 210,000, reducing the block reward from 50 to 25 BTC."},{"q":"Which hard fork of Bitcoin occurred on August 1, 2017, creating a new cryptocurrency with larger blocks?","options":["Bitcoin Cash","Bitcoin Gold","Bitcoin SV","Bitcoin Diamond"],"answer":0,"explanation":"Bitcoin Cash (BCH) forked from Bitcoin on August 1, 2017, increasing the block size limit from 1 MB to 8 MB."},{"q":"Satoshi's last widely cited message was an email to whom?","options":["Gavin Andresen, in December 2010","Mike Hearn, on April 23, 2011","Hal Finney, on January 12, 2009","Adam Back, in August 2008"],"answer":1,"explanation":"The note \"I've moved on to other things\" is in Satoshi's April 23, 2011 email to Mike Hearn. Later retellings sometimes name Gavin. The last public forum posts were in December 2010."},{"q":"What event is known as the 'Blocksize War'?","options":["The competition between Bitcoin and Bitcoin Cash miners","The 2013 fork caused by a software bug","The 2015-2017 debate over increasing Bitcoin's block size","The 2018 hash war between Bitcoin ABC and Bitcoin SV"],"answer":2,"explanation":"The Blocksize War was a multi-year debate (2015-2017) over whether to increase Bitcoin's block size, ultimately resolved with SegWit activation and the Bitcoin Cash fork."},{"q":"Which upgrade activated on Bitcoin in August 2017, fixing transaction malleability?","options":["Pay-to-Script-Hash","Taproot","CheckSequenceVerify","Segregated Witness (SegWit)"],"answer":3,"explanation":"SegWit separated signature data from transaction data, fixing the transaction malleability bug and enabling second-layer solutions like Lightning Network."},{"q":"What is the name of the domain where the Bitcoin whitepaper was originally hosted?","options":["bitcoin.org","bitcoin.com","bitcointalk.org","sourceforge.net"],"answer":0,"explanation":"Satoshi registered bitcoin.org in August 2008 and published the whitepaper there in October 2008."},{"q":"Which BIP specifies bech32 for native SegWit version-0 addresses?","options":["BIP 32","BIP 173","BIP 39","BIP 141"],"answer":1,"explanation":"BIP 173 defines bech32, the \"Base32 address format for native v0-16 witness outputs.\" BIP 350 later kept bech32 for version 0 and switched version 1 and later to bech32m. Source: https://github.com/bitcoin/bips/blob/master/bip-0173.mediawiki"},{"q":"When did the Taproot upgrade activate on Bitcoin?","options":["November 2020","August 2017","November 2021","June 2022"],"answer":2,"explanation":"Taproot activated at block 709,632 on November 14, 2021, bringing Schnorr signatures and improved smart contract capabilities."},{"q":"What hashing algorithm does Bitcoin use for mining (proof of work)?","options":["Blake2b","Scrypt","Ethash","SHA-256"],"answer":3,"explanation":"Bitcoin uses the SHA-256 (Secure Hash Algorithm 256-bit) hashing function, which miners must repeatedly compute to find valid blocks."},{"q":"How often does Bitcoin's mining difficulty adjust?","options":["Every 2,016 blocks (~2 weeks)","Every 1,000 blocks (~1 week)","Every 4,032 blocks (~4 weeks)","Every block"],"answer":0,"explanation":"Bitcoin adjusts difficulty every 2,016 blocks (approximately every two weeks) to maintain the target of one block every ~10 minutes."},{"q":"What is the maximum size of a legacy Bitcoin block?","options":["2 MB","1 MB","4 MB","8 MB"],"answer":1,"explanation":"Legacy Bitcoin blocks are limited to 1 MB. With SegWit, the effective limit is measured in weight units, allowing up to about 4 MB of total block weight."},{"q":"What does UTXO stand for in Bitcoin?","options":["Universal Token Transfer Object","Unified Transaction Exchange Order","Unspent Transaction Output","Unsigned Transaction Operation"],"answer":2,"explanation":"UTXOs are Unspent Transaction Outputs — the fundamental building blocks of Bitcoin's accounting model, representing spendable coins."},{"q":"What is the target average time between Bitcoin blocks?","options":["1 minute","5 minutes","15 minutes","10 minutes"],"answer":3,"explanation":"Bitcoin's difficulty adjustment algorithm targets an average block time of 10 minutes, though individual blocks can vary significantly."},{"q":"What is a Bitcoin mempool?","options":["A waiting area for unconfirmed transactions","A pool of mining hardware","A type of memory storage for nodes","A collection of expired blocks"],"answer":0,"explanation":"The mempool (memory pool) is where valid but unconfirmed transactions wait before being included in a block by miners."},{"q":"What type of cryptography does Bitcoin use for digital signatures?","options":["RSA","Elliptic Curve Digital Signature Algorithm (ECDSA)","Diffie-Hellman","AES-256"],"answer":1,"explanation":"Bitcoin originally uses ECDSA with the secp256k1 curve for signing transactions. Taproot added support for Schnorr signatures."},{"q":"What is a Merkle tree used for in Bitcoin?","options":["Encrypting private keys","Generating new Bitcoin addresses","Efficiently summarizing and verifying all transactions in a block","Routing payments across the network"],"answer":2,"explanation":"A Merkle tree hashes all transactions in a block into a single root hash, allowing efficient verification that a specific transaction is included in a block."},{"q":"How many confirmations are generally considered secure for a large Bitcoin transaction?","options":["10 confirmations","1 confirmation","3 confirmations","6 confirmations"],"answer":3,"explanation":"Six confirmations (~60 minutes) is the traditional threshold for considering a transaction practically irreversible, though smaller transactions may require fewer."},{"q":"What is the Bitcoin scripting language called?","options":["Script","Solidity","Clarity","Move"],"answer":0,"explanation":"Bitcoin uses a stack-based scripting language simply called 'Script.' It is intentionally not Turing-complete to reduce attack surfaces."},{"q":"SegWit's consensus limit on a block is measured as what?","options":["1 megabyte of witness data free of charge","4,000,000 weight units","7 transactions and then a hard stop","21 million bytes"],"answer":1,"explanation":"4,000,000 weight units equals 1,000,000 virtual bytes. A virtual byte is weight divided by four. It is the same limit in different units, not a rival rule."},{"q":"What is a nonce in Bitcoin mining?","options":["The network fee attached to a transaction","A one-time cryptographic key for transactions","A number miners change to produce a valid block hash","A unique identifier for each Bitcoin address"],"answer":2,"explanation":"The nonce is a 32-bit field in the block header that miners increment to find a hash below the target difficulty."},{"q":"What is an SPV (Simplified Payment Verification) node?","options":["A node that processes only SegWit transactions","A node that only stores the most recent 100 blocks","A mining node with simplified hardware","A lightweight node that verifies transactions using block headers without downloading the full blockchain"],"answer":3,"explanation":"SPV nodes download only block headers and use Merkle proofs to verify transactions, as described in Satoshi's whitepaper, enabling lightweight wallets."},{"q":"What is the coinbase transaction?","options":["The first transaction in every block that creates new bitcoins as a mining reward","A transaction on the Coinbase exchange","The very first Bitcoin transaction ever made","A transaction that destroys bitcoins permanently"],"answer":0,"explanation":"The coinbase transaction is the first transaction in each block, created by the miner, which generates new BTC (the block subsidy) plus collects transaction fees."},{"q":"What is the maximum number of weight units allowed in a Bitcoin block?","options":["1,000,000 WU","4,000,000 WU","2,000,000 WU","8,000,000 WU"],"answer":1,"explanation":"Post-SegWit, Bitcoin blocks are limited to 4 million weight units. Non-witness data counts as 4 WU per byte, while witness data counts as 1 WU per byte."},{"q":"What is the maximum supply of Bitcoin?","options":["100 million","18 million","21 million","42 million"],"answer":2,"explanation":"Bitcoin's protocol enforces a hard cap of 21 million coins, making it the first provably scarce digital asset."},{"q":"How often does the Bitcoin block reward halve?","options":["Every year","Every 100,000 blocks (~2 years)","Every 500,000 blocks (~10 years)","Every 210,000 blocks (~4 years)"],"answer":3,"explanation":"The block reward halves every 210,000 blocks, approximately every four years, reducing the rate of new Bitcoin creation."},{"q":"What was the block reward after the 2024 halving?","options":["3.125 BTC","6.25 BTC","1.5625 BTC","12.5 BTC"],"answer":0,"explanation":"The April 2024 halving (the fourth) reduced the block reward from 6.25 BTC to 3.125 BTC per block."},{"q":"About what share of the 21 million bitcoin had been issued by 2026?","options":["About half","About 95 percent","About 75 percent","All of them"],"answer":1,"explanation":"Issuance was a bit under 20 million of the 21 million cap by 2026, about 95 percent. The exact count moves with each block. The last coins are scheduled out toward 2140."},{"q":"What is the smallest unit of Bitcoin called?","options":["Finney","Wei","Satoshi","Gwei"],"answer":2,"explanation":"A satoshi (sat) is 0.00000001 BTC — one hundred millionth of a bitcoin, named after Bitcoin's creator."},{"q":"What economic concept does the stock-to-flow model measure?","options":["The total market capitalization divided by trading volume","The velocity of money in the Bitcoin network","The ratio of buy orders to sell orders","The ratio of existing supply to annual production"],"answer":3,"explanation":"Stock-to-flow divides existing supply (stock) by annual new production (flow). Bitcoin's ratio increases with each halving, similar to gold and silver."},{"q":"In approximately what year will the last Bitcoin be mined?","options":["2140","2100","2050","2200"],"answer":0,"explanation":"Due to the halving schedule, the block reward will become negligibly small, with the last satoshi expected to be mined around the year 2140."},{"q":"What happens to Bitcoin miners' revenue when the block subsidy eventually reaches zero?","options":["Mining will stop and the network will shut down","They will rely entirely on transaction fees","A new subsidy will be voted on by miners","Miners will be paid by the Bitcoin Foundation"],"answer":1,"explanation":"Once all 21 million BTC are mined, miners will be incentivized solely by transaction fees included in each block."},{"q":"What is the term for the reduction in Bitcoin's annual inflation rate after each halving?","options":["Hyperinflationary","Deflationary","Disinflationary","Reflationary"],"answer":2,"explanation":"Bitcoin is disinflationary — new coins are still created, but at a decreasing rate. After all coins are mined, lost coins make the effective supply deflationary."},{"q":"What does 'difficulty epoch' refer to in Bitcoin?","options":["A period when no blocks are found for over an hour","A period of extreme price volatility","The time between two halvings","A period of 2,016 blocks between difficulty adjustments"],"answer":3,"explanation":"A difficulty epoch is the 2,016-block window (~2 weeks) after which Bitcoin's proof-of-work difficulty is recalculated."},{"q":"What is the 'block subsidy' in Bitcoin?","options":["The newly created BTC awarded to the miner who finds a block","A fee paid by users to prioritize transactions","A fund maintained by Bitcoin Core developers","The cost of electricity required to mine a block"],"answer":0,"explanation":"The block subsidy is the newly minted BTC in each block's coinbase transaction. It started at 50 BTC and halves every 210,000 blocks."},{"q":"What is a 'fee market' in Bitcoin?","options":["An exchange where miners sell their block rewards","Competition among users to have their transactions included by paying higher fees","A marketplace for buying and selling Bitcoin mining contracts","A derivatives market for hedging transaction costs"],"answer":1,"explanation":"When block space is scarce, users compete by offering higher fees to incentivize miners to include their transactions, creating a fee market."},{"q":"How many satoshis are in one Bitcoin?","options":["1,000,000","10,000,000","100,000,000","1,000,000,000"],"answer":2,"explanation":"One Bitcoin equals 100 million satoshis. This high divisibility allows Bitcoin to be used for microtransactions."},{"q":"What is the term for Bitcoin that has been sent to an unspendable address, permanently removing it from circulation?","options":["Protocol bonded","Permanently staked","Vault locked","Burned"],"answer":3,"explanation":"Burning Bitcoin means sending it to a provably unspendable address (like an address with no known private key), permanently reducing the circulating supply."},{"q":"Where does the term 'HODL' originate?","options":["A misspelled forum post on BitcoinTalk in 2013","An acronym coined by Satoshi Nakamoto in the whitepaper","A Wall Street trading strategy adapted for crypto","A meme that first appeared on Reddit in early 2015"],"answer":0,"explanation":"HODL originated from a typo in a 2013 BitcoinTalk forum post titled 'I AM HODLING' by user GameKyuubi during a price crash."},{"q":"What does the phrase 'Not your keys, not your coins' mean?","options":["You need physical keys to access Bitcoin ATMs","If you don't control your private keys, you don't truly own your Bitcoin","Bitcoin can only be sent using hardware wallets","Exchanges always guarantee the safety of your funds"],"answer":1,"explanation":"This phrase warns that Bitcoin held on exchanges or custodial services can be lost if the custodian is hacked or goes bankrupt, as happened with Mt. Gox."},{"q":"What does it mean when someone says they have 'laser eyes' on social media?","options":["They run a large-scale Bitcoin mining operation using proof-of-work hardware","They are a Bitcoin Core developer who has contributed code to the protocol","They are bullish on Bitcoin and showing support for a BTC price target","They have completed an on-chain identity verification through a smart contract"],"answer":2,"explanation":"Laser eyes became a Bitcoin meme in 2021, with supporters adding laser eyes to profile photos to signal bullishness and support for Bitcoin reaching $100K."},{"q":"What is a 'Bitcoin Maximalist'?","options":["A developer who has contributed the most lines of code to Bitcoin Core software","A person who owns the maximum possible amount of Bitcoin in a single wallet","A miner running the most powerful hardware available for proof of work","Someone who believes Bitcoin is the only cryptocurrency that matters"],"answer":3,"explanation":"Bitcoin Maximalists (or 'maxis') believe Bitcoin is the only legitimate cryptocurrency and that altcoins are unnecessary or harmful."},{"q":"What does 'number go up' (NGU) technology refer to in Bitcoin culture?","options":["The humorous observation that Bitcoin's price trends upward over long periods","A proposed technical improvement to increase Bitcoin transaction throughput speed","An algorithm designed to automatically increase the mining difficulty over time","A data compression method for reducing the size of the blockchain on full nodes"],"answer":0,"explanation":"'NGU technology' is a tongue-in-cheek meme celebrating Bitcoin's long-term price appreciation as if it were a feature of the protocol."},{"q":"What does 'stacking sats' mean?","options":["Building a physical stack of ASIC mining rigs for profit","Accumulating small amounts of Bitcoin over time","Organizing satellite nodes for the Bitcoin network","Compiling and organizing Bitcoin transaction data locally"],"answer":1,"explanation":"Stacking sats means regularly buying small amounts of Bitcoin (measured in satoshis), often through dollar-cost averaging."},{"q":"Who is often credited with conceptualizing digital cash and 'bit gold' before Bitcoin?","options":["David Chaum","Satoshi Nakamoto","Nick Szabo","Hal Finney Jr."],"answer":2,"explanation":"Nick Szabo proposed 'Bit Gold' in 1998, a decentralized digital currency concept that shares many similarities with Bitcoin."},{"q":"What is the 'Citadel' meme in Bitcoin culture?","options":["A well-known cooperative Bitcoin mining pool that early adopters frequently joined","A type of ultra-secure cold storage Bitcoin vault system with multisig protection","The rumored physical headquarters of the anonymous Bitcoin Foundation leadership","A future scenario where early Bitcoin adopters live in fortified communities"],"answer":3,"explanation":"The Citadel meme imagines a hyperbitcoinized future where early adopters live in citadels, originating from a famous Reddit post claiming to be from the year 2025."},{"q":"What does 'FUD' stand for in crypto communities?","options":["Fear, Uncertainty, and Doubt","Fully Utilized Decentralization","Future Unlimited Digital Dividends","Fundamentally Unverified Data"],"answer":0,"explanation":"FUD (Fear, Uncertainty, and Doubt) refers to negative information or sentiment spread to discourage people from buying or holding Bitcoin."},{"q":"What is a 'whole coiner' in Bitcoin terminology?","options":["A miner who has mined an entire block solo","Someone who owns at least 1 full Bitcoin","A full node operator running the Bitcoin Core software","Someone who has read the entire Bitcoin whitepaper"],"answer":1,"explanation":"A 'whole coiner' is someone who owns at least one complete Bitcoin. With Bitcoin's rising price, this has become an aspirational milestone."},{"q":"Who wrote 'The Bitcoin Standard,' an influential book on Bitcoin's monetary properties?","options":["Jameson Lopp, Jr.","Andreas Antonopoulos","Saifedean Ammous","Michael J. Saylor"],"answer":2,"explanation":"Saifedean Ammous published 'The Bitcoin Standard' in 2018, arguing for Bitcoin as sound money through the lens of Austrian economics."},{"q":"What does 'HFSP' stand for in Bitcoin Twitter culture?","options":["Halving Follows Supply Pattern","Hyper-Funded Protocol","Hash Function Security Protocol for Blockchain Networks","Have Fun Staying Poor"],"answer":3,"explanation":"'Have Fun Staying Poor' is a dismissive phrase used by Bitcoin enthusiasts toward skeptics, popularized on Twitter/X by Bitcoin maximalists."},{"q":"What is the significance of the Bitcoin 'B' symbol (₿)?","options":["It was adopted as the official Unicode symbol for Bitcoin in 2017","It was designed by Satoshi Nakamoto in 2008","It represents the binary nature of digital currency","It was created by the Bitcoin Foundation in 2014"],"answer":0,"explanation":"The ₿ symbol was added to the Unicode Standard in June 2017 (Unicode 10.0), giving Bitcoin an official currency symbol alongside $, €, and ¥."},{"q":"Who is credited with buying the pizzas Laszlo offered bitcoin for?","options":["A London pizzeria that called Florida","Forum user jercos, Jeremy Sturdivant","Satoshi Nakamoto in person","Hal Finney from California"],"answer":1,"explanation":"Laszlo posted the offer on BitcoinTalk on May 18, 2010. Jeremy Sturdivant, known as jercos, bought the pizzas. Reports place the purchase in the United States. May 22 is the day associated with the meal."},{"q":"What is the Lightning Network?","options":["A mining pool that processes transactions faster","A faster version of the Bitcoin blockchain","A Layer 2 payment protocol built on top of Bitcoin for fast, cheap transactions","An alternative cryptocurrency inspired by Bitcoin"],"answer":2,"explanation":"The Lightning Network is a Layer 2 protocol that enables near-instant, low-fee Bitcoin payments through a network of payment channels."},{"q":"What must two parties open to transact on the Lightning Network?","options":["An independent Bitcoin sidechain connection","A shared mining operation pool","A dedicated smart contract address","A payment channel"],"answer":3,"explanation":"Lightning Network participants open payment channels by locking Bitcoin in a 2-of-2 multisig on-chain transaction, then transact off-chain within that channel."},{"q":"Who authored the original Lightning Network whitepaper?","options":["Joseph Poon and Thaddeus Dryja","Nakamoto and Finney","Gregory Maxwell and Adam Back together","Elizabeth Stark with Olaoluwa Osuntokun"],"answer":0,"explanation":"Joseph Poon and Thaddeus Dryja wrote \"The Bitcoin Lightning Network.\" It was drafted in 2015, and the final version is dated January 2016. It describes the off-chain payment channel network."},{"q":"What Bitcoin feature was essential for the Lightning Network to work safely?","options":["The Taproot soft fork upgrade","Segregated Witness (SegWit)","Bitcoin's Replace-by-Fee transaction mechanism","The OP_RETURN data embedding function"],"answer":1,"explanation":"SegWit fixed the transaction malleability problem, which was essential because Lightning relies on pre-signed transactions referencing specific transaction IDs."},{"q":"What happens when a Lightning Network channel is closed?","options":["All locked funds are completely destroyed and then freshly re-minted as new coins","Every individual transaction from the channel is permanently recorded on-chain in full detail","The final balance is settled on the Bitcoin blockchain","It reopens"],"answer":2,"explanation":"When a Lightning channel closes, a final settlement transaction is broadcast to the Bitcoin blockchain reflecting the latest balance between the two parties."},{"q":"What is 'routing' in the Lightning Network?","options":["Selecting the fastest blockchain for settlement","Directing mining power to specific blocks","Choosing which Bitcoin node to connect to","Finding a path of connected channels to send a payment to someone you don't have a direct channel with"],"answer":3,"explanation":"Lightning routing finds multi-hop paths through the network, allowing payments between parties who don't share a direct channel."},{"q":"What is an 'invoice' in the Lightning Network?","options":["A payment request containing amount, destination, and expiry encoded in a string","A record of all channel openings on the network","A tax document for Lightning transactions","A receipt generated after an on-chain transaction"],"answer":0,"explanation":"A Lightning invoice (BOLT 11) is a payment request that encodes the payment hash, amount, destination node, and expiry time."},{"q":"What is 'channel capacity' on the Lightning Network?","options":["Maximum transactions processed","The total amount of Bitcoin locked in a payment channel","The total bandwidth and speed capacity of a Lightning node's dedicated internet connection","How many simultaneous channels one node opens"],"answer":1,"explanation":"Channel capacity is the total Bitcoin locked in the channel's funding transaction. Payments within the channel cannot exceed this amount."},{"q":"What is a 'watchtower' in the context of Lightning Network?","options":["A mandatory government-run surveillance tool used for actively monitoring and tracking all Bitcoin transactions on the public network","Enhanced full nodes","A service that monitors channels and broadcasts penalty transactions if a counterparty cheats","A node that validates Lightning invoices"],"answer":2,"explanation":"Watchtowers protect Lightning users by monitoring the blockchain for fraudulent channel closes and broadcasting penalty transactions on their behalf."},{"q":"What is the unit typically used for Lightning Network payments?","options":["Special Lightning network credits","Millisatoshis or msats","Whole Bitcoin units only","Satoshis (sats)"],"answer":3,"explanation":"While the Lightning Network internally tracks millisatoshis (1/1000th of a sat), payments are typically denominated in satoshis."},{"q":"Which popular Lightning Network implementation is developed by Lightning Labs?","options":["LND","Core Lightning (CLN)","The Eclair implementation","Electrum Lightning Extension"],"answer":0,"explanation":"LND (Lightning Network Daemon) is developed by Lightning Labs and is one of the most widely used Lightning implementations."},{"q":"What is a 'submarine swap' in Bitcoin's Lightning ecosystem?","options":["Cross-blockchain token swapping","An atomic swap between on-chain Bitcoin and Lightning Bitcoin","A privacy method for concealing Lightning payment amounts from observers","A technique for merging channels together"],"answer":1,"explanation":"Submarine swaps allow trustless exchanges between on-chain and off-chain (Lightning) Bitcoin, useful for channel rebalancing and liquidity management."},{"q":"What is 'inbound liquidity' on the Lightning Network?","options":["The rate at which new channels are opened to your node","The total Bitcoin you have locked in all your channels","The amount of Bitcoin on the remote side of your channels that others can send to you","The speed at which your node processes incoming payments"],"answer":2,"explanation":"Inbound liquidity is the capacity others have to send you payments. New channels start with all funds on your side (outbound only), making inbound liquidity a common challenge."},{"q":"What is BOLT in the context of Lightning Network?","options":["Binary Optimized Lightning Transfer protocol specifications","Off-chain Ledger Technology","A popular and widely-used mobile wallet application designed for everyday Lightning payments","Basis of Lightning Technology — the specification documents for Lightning"],"answer":3,"explanation":"BOLT (Basis of Lightning Technology) is the set of specification documents that define how Lightning Network implementations should operate and interoperate."},{"q":"What is a 'seed phrase' (mnemonic phrase) in Bitcoin?","options":["A set of 12 or 24 words that can recover a Bitcoin wallet","A password used to encrypt the blockchain","A secret code shared between miners","The genesis block's encoded message"],"answer":0,"explanation":"A seed phrase (BIP-39) is a human-readable representation of a wallet's master private key. Anyone with the phrase can reconstruct and access the wallet."},{"q":"What is 'cold storage' in Bitcoin?","options":["Storing Bitcoin in a refrigerated data center","Keeping private keys on a device that is never connected to the internet","Freezing a Bitcoin account on an exchange","A method of compressing blockchain data for archival"],"answer":1,"explanation":"Cold storage means storing private keys offline (hardware wallets, paper wallets, air-gapped computers), protecting them from online hacks."},{"q":"What is multisignature (multisig) in Bitcoin?","options":["The requirement for multiple blockchain confirmations before considering a transaction valid","Miner-signed transactions","A setup requiring multiple private keys to authorize a transaction","A multi-cryptocurrency wallet supporting various coins"],"answer":2,"explanation":"Multisig requires M-of-N private keys to spend (e.g., 2-of-3), adding security by ensuring no single key compromise can move funds."},{"q":"CoinJoin, the privacy idea Gregory Maxwell described in 2013, does what?","options":["Consolidating multiple UTXOs into a single output","Wallet merging protocol","A standard protocol used for joining and coordinating mining pools together","A privacy technique that combines multiple users' transactions into one"],"answer":3,"explanation":"CoinJoin mixes multiple users' inputs and outputs in a single transaction, making it harder to trace which input corresponds to which output."},{"q":"What is a '51% attack' in Bitcoin?","options":["When a single entity controls more than half the network's mining power, enabling double-spends","When 51% of nodes reject a software update","When a wallet loses more than 51% of its funds","When 51% of all Bitcoin is held by one address"],"answer":0,"explanation":"A 51% attack allows an entity controlling majority hash power to reorganize blocks and double-spend, though it's prohibitively expensive on Bitcoin's network."},{"q":"What is a hardware wallet?","options":["A dedicated full-node computer","A physical device that stores private keys offline and signs transactions securely","A specialized USB drive that contains a fully complete and synchronized copy of the entire Bitcoin blockchain","Specialized mining rig hardware"],"answer":1,"explanation":"Hardware wallets (like Ledger, Trezor, Coldcard) store private keys in secure hardware, signing transactions without exposing keys to potentially compromised computers."},{"q":"What is a 'dusting attack' in Bitcoin?","options":["Simultaneously stealing very small fractional amounts from thousands of different wallets at once","Network spam flooding","Sending tiny amounts of BTC to many addresses to track spending patterns","Mining intentionally empty blocks to slow network"],"answer":2,"explanation":"In a dusting attack, tiny amounts of BTC (dust) are sent to many addresses. If recipients spend the dust, analysts can link addresses and deanonymize users."},{"q":"What does BIP-39 define?","options":["Bitcoin's mining difficulty adjustment algorithm","SegWit format","The Lightning Network's standardized routing and payment channel protocol specification document","The mnemonic code standard for generating deterministic wallets"],"answer":3,"explanation":"BIP-39 defines the standard for mnemonic seed phrases (12/24 words from a 2048-word list) used to generate deterministic wallet keys."},{"q":"What is a 'passphrase' (25th word) in the context of seed phrases?","options":["An optional extra word added to a seed phrase that creates a completely different wallet","The last word in a 24-word seed phrase","The password to unlock a hardware wallet","A recovery phrase used if you forget your PIN"],"answer":0,"explanation":"An optional passphrase (sometimes called the 25th word) extends the seed phrase. Different passphrases derive completely different wallets, enabling plausible deniability."},{"q":"What is the purpose of a Bitcoin 'watch-only' wallet?","options":["Real-time price observation","To monitor a wallet's balance and transactions without the ability to spend","A tool for monitoring the full mempool for any specific pending transaction activity","Watching other users' blockchain activity"],"answer":1,"explanation":"Watch-only wallets import only public keys (xpub), allowing balance monitoring without the private keys needed to spend — useful for tracking cold storage."},{"q":"What is a 'time-lock' in Bitcoin transactions?","options":["A lock on an exchange account after failed login attempts","A limit on how long a transaction stays in the mempool","A condition that prevents a transaction from being spent until a specified block height or time","A scheduled automatic Bitcoin purchase"],"answer":2,"explanation":"Time-locks (nLockTime, OP_CLTV, OP_CSV) restrict when a transaction output can be spent, enabling features like payment channels, inheritance planning, and vaults."},{"q":"Why is address reuse considered bad practice in Bitcoin?","options":["It directly violates Bitcoin protocol rules","Address expiration","It significantly and noticeably increases the transaction fees that are charged by the entire Bitcoin network","It reduces privacy by linking multiple transactions to the same address"],"answer":3,"explanation":"Reusing addresses makes it easy for blockchain analysts to link your transactions and build a profile of your spending habits, reducing financial privacy."},{"q":"What is a 'brain wallet' and why is it dangerous?","options":["A wallet generated from a memorized passphrase, vulnerable to brute-force attacks","AI-powered trading wallet","A wallet securely stored and distributed across multiple cloud-based neural network infrastructure systems worldwide","Quantum-resistant wallet design"],"answer":0,"explanation":"Brain wallets derive private keys from memorized phrases, but humans choose predictable phrases. Attackers pre-compute keys from common phrases and steal funds."},{"q":"What does 'coin control' refer to in Bitcoin wallets?","options":["Setting limits on how much Bitcoin can be sent per day","Manually selecting which UTXOs to use when constructing a transaction","A government regulatory framework for Bitcoin","Controlling the rate at which new coins are mined"],"answer":1,"explanation":"Coin control lets users choose specific UTXOs for a transaction, improving privacy by avoiding linking unrelated UTXOs and managing change outputs."},{"q":"Which country became the first to adopt Bitcoin as legal tender in 2021?","options":["The nation of Panama","The Republic of Paraguay","El Salvador","Central American Honduras"],"answer":2,"explanation":"El Salvador, under President Nayib Bukele, passed the Bitcoin Law in June 2021, making Bitcoin legal tender alongside the US dollar."},{"q":"What is El Salvador's government-backed Bitcoin wallet called?","options":["Strike Global","Muun Wallet","BlueWallet Lightning","Chivo"],"answer":3,"explanation":"Chivo Wallet was launched by the Salvadoran government in September 2021 to facilitate Bitcoin and dollar transactions for citizens."},{"q":"In January 2024, the SEC approved which type of Bitcoin investment product?","options":["Spot Bitcoin ETFs","Bitcoin futures exchange-traded funds","Standardized Bitcoin options trading contracts","Government-backed Bitcoin savings bonds"],"answer":0,"explanation":"The SEC approved 11 spot Bitcoin ETFs on January 10, 2024, allowing traditional investors to gain exposure to Bitcoin through regulated brokerage accounts."},{"q":"Which company, led by Michael Saylor, became famous for its massive Bitcoin treasury holdings?","options":["Tesla Motors Inc","MicroStrategy","Block (formerly Square)","Galaxy Digital Holdings"],"answer":1,"explanation":"MicroStrategy (now Strategy), under CEO Michael Saylor, began buying Bitcoin in August 2020 and accumulated hundreds of thousands of BTC as a treasury reserve."},{"q":"Which major electric vehicle company announced a $1.5 billion Bitcoin purchase in February 2021?","options":["Lucid Motors Group","Rivian Automotive","Tesla","NIO Electric Vehicles"],"answer":2,"explanation":"Tesla disclosed a $1.5 billion Bitcoin purchase in an SEC filing in February 2021, briefly accepting BTC for vehicle purchases."},{"q":"What is the primary environmental criticism of Bitcoin mining?","options":["Deforestation to build mining farms","E-waste","Excessive industrial water usage needed for cooling large mining facility operations","High energy consumption from proof-of-work mining"],"answer":3,"explanation":"Critics argue Bitcoin's proof-of-work consensus requires significant electricity. Proponents counter that a growing portion comes from renewable sources and stranded energy."},{"q":"What is the Bitcoin Mining Council?","options":["A voluntary group of mining companies that promotes transparency about energy usage","Government mining regulator","An official centralized government organization that directly allocates and controls Bitcoin mining difficulty adjustment settings","A consortium controlling Bitcoin hash rate"],"answer":0,"explanation":"The Bitcoin Mining Council, formed in 2021, is a voluntary forum of mining companies that collects and shares data on Bitcoin mining's energy mix and sustainability."},{"q":"Which African country's central bank issued warnings about Bitcoin while the country saw rapid grassroots adoption?","options":["East African Kenya","Nigeria","Republic of South Africa","West African Ghana"],"answer":1,"explanation":"Nigeria's central bank restricted bank-to-crypto transactions in 2021, yet Nigeria remained one of the top countries for Bitcoin peer-to-peer trading volume."},{"q":"Which products has Block, formerly Square, kept working on for Bitcoin?","options":["A private chain called Squarecoin","Only the shut-down TBD project","Cash App, the Bitkey wallet, and Proto miners","The Federal Reserve's retail CBDC"],"answer":2,"explanation":"Cash App is Block's consumer app. Bitkey is its hardware wallet. Proto is its mining hardware. The TBD identity effort, including the Web5 pitch, was shut down in late 2024."},{"q":"What was the significance of China's Bitcoin mining ban in 2021?","options":["It led to a change in Bitcoin's proof-of-work algorithm","It permanently reduced Bitcoin's total hash rate","It caused Bitcoin's price to crash to zero briefly","It caused a massive hash rate migration and redistribution of mining to other countries"],"answer":3,"explanation":"China's mining crackdown caused ~50% of Bitcoin's hash rate to go offline temporarily, leading to miners relocating to the US, Kazakhstan, Canada, and other countries."},{"q":"What did El Salvador build to mine Bitcoin using geothermal energy?","options":["A Bitcoin mining facility powered by a volcano","Hydroelectric mining dam","A large dedicated solar-powered cryptocurrency mining farm operation built in the desert","A wind operation"],"answer":0,"explanation":"El Salvador announced plans to use geothermal energy from volcanoes to power Bitcoin mining, setting up initial mining operations near the Tecapa volcano."},{"q":"Which payment company launched Bitcoin buying and selling for its hundreds of millions of users in 2020?","options":["Venmo Mobile Payments","PayPal","Stripe Payment Processing","Zelle Bank Transfers"],"answer":1,"explanation":"PayPal announced Bitcoin buying, selling, and holding for US users in October 2020, later expanding to Venmo and international markets."},{"q":"What is a 'Bitcoin bond' as proposed by El Salvador?","options":["A bond instrument that automatically converts its full face value to Bitcoin at maturity","Interest-in-Bitcoin corporate bond","A government bond partially backed by Bitcoin, aimed at funding Bitcoin City","A decentralized finance lending instrument"],"answer":2,"explanation":"El Salvador proposed 'Volcano Bonds' — government securities partially backed by Bitcoin — to fund Bitcoin City and Bitcoin purchases, structured with Blockstream."},{"q":"What is the significance of the 'HODL Waves' chart?","options":["New wallet creation trends over time","Social media HODL tracking","A chart measuring the precise frequency and intensity of price volatility during market cycles","It shows the age distribution of all UTXOs, revealing holding behavior patterns"],"answer":3,"explanation":"HODL Waves visualize what percentage of Bitcoin supply has remained unmoved for various time periods, revealing long-term holding conviction during market cycles."},{"q":"Laszlo's pizza offer and the day the pizzas arrived are separated how?","options":["Offered May 18, 2010; remembered on May 22","Both happened on January 3, 2009","Offered in 2011 after the first halving","Paid in dollars, not in bitcoin"],"answer":0,"explanation":"The BitcoinTalk offer is dated May 18, 2010: 10,000 bitcoins for a couple of pizzas. Pizza Day is May 22, the day associated with the delivery. The two dates are easy to merge in retellings."},{"q":"What date is celebrated as Bitcoin Pizza Day?","options":["January 3","May 22","October 31","April 21"],"answer":1,"explanation":"May 22, 2010 — the day Laszlo Hanyecz completed the first known commercial Bitcoin transaction: 10,000 BTC for two pizzas."},{"q":"New Liberty Standard's October 5, 2009 post quoted bitcoin at about what rate?","options":["100 bitcoin per dollar in 2010","One dollar per bitcoin","1,309.03 BTC per one US dollar","The same price as an ounce of gold"],"answer":2,"explanation":"The post priced bitcoin from electricity cost: 1,309.03 BTC for $1, about $0.00076 per bitcoin. It is dated October 5, 2009, not 2010, and it was not a brokerage ticker."},{"q":"In January 2025, El Salvador adjusted its Bitcoin law so that merchants:","options":["Replaced the dollar with bitcoin overnight","Had to settle every tax only in bitcoin","Lost the right to hold bitcoin at all","No longer had to accept bitcoin"],"answer":3,"explanation":"The 2021 law had made bitcoin legal tender. Under a 2025 IMF program, acceptance by businesses became voluntary and the state Chivo wallet was being wound down. People can still use bitcoin."},{"q":"What was unusual about the Bitcoin genesis block's 50 BTC reward?","options":["It cannot be spent due to a quirk in the protocol","It was immediately sent to Hal Finney","It was mined by accident with no difficulty target","It was double the normal block reward"],"answer":0,"explanation":"The protocol requires that the 50 BTC in block 0 (the genesis block) cannot be transferred — they are effectively unspendable and do not count toward the circulating supply."},{"q":"The timestamp gap from the genesis block to block 1 is about how long?","options":["Ten minutes, as the target intends","About six days, January 3 to January 9, 2009","A full difficulty epoch of two weeks","The four years until the first halving"],"answer":1,"explanation":"Block 0 is timestamped January 3, 2009 and block 1 January 9. That gap is not proof of how long the hash search took. It is only the difference in the recorded times."},{"q":"Which genesis output can the protocol itself not spend?","options":["The 10 BTC Hal received in block 170","Every later gift sent to that same address","The original 50 BTC coinbase of block 0","Any coinbase newer than 100 blocks"],"answer":2,"explanation":"The client never puts the genesis coinbase into the spendable set. Later tribute payments to 1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa are ordinary outputs. They are stuck only if nobody has the key."},{"q":"What did Hal Finney's January 11, 2009 tweet say?","options":["Banning bitcoin","Selling bitcoin","Forking bitcoin","Running bitcoin"],"answer":3,"explanation":"The tweet is the two words \"Running bitcoin,\" at 03:33 UTC on January 11, 2009 (the evening of January 10 in California). Source: https://x.com/halfin/status/1110302988 . The 10 BTC transfer in block 170 is the next day, January 12, 2009 (UTC)."},{"q":"What is a careful description of the code Satoshi published in 2009?","options":["A small open-source C++ client, with no agreed public line count","Exactly 31,000 lines, frozen and never edited","A million-line enterprise suite","Only the nine-page whitepaper, and no program"],"answer":0,"explanation":"He published a working open-source client in 2009. Repeated line counts such as 31,000 have no primary source that settles a number, so this item does not use one."},{"q":"How much of today's Bitcoin Core is still Satoshi's original wording?","options":["Exactly half, by an official Core report","Most of it has been revised; there is no settled 0.06% figure","None of the ideas, and none of the files, were ever his","All of it, byte for byte, in the current release"],"answer":1,"explanation":"The codebase has been edited for years. A precise \"0.06% unchanged\" figure has no documented source, so it is not stated here as a fact."},{"q":"How many confirmations must newly mined Bitcoin wait before it can be spent?","options":["6 confirmations","1 confirmation","101 confirmations","21 confirmations"],"answer":2,"explanation":"Mined (coinbase) Bitcoin cannot be spent until it has 101 confirmations — roughly 16+ hours. This prevents issues if an early block gets orphaned."},{"q":"What is the default mempool size for a Bitcoin node?","options":["10 MB","1 GB","50 MB","300 MB"],"answer":3,"explanation":"By default, a Bitcoin node allocates 300 MB for its mempool — the waiting area for unconfirmed transactions. This can be adjusted in the node's configuration file."},{"q":"How many nodes does a Bitcoin node connect to by default?","options":["10 other nodes","100 nodes","1 node","50 nodes"],"answer":0,"explanation":"By default, a Bitcoin node connects to 10 other nodes at any one time. This can be changed in the bitcoin.conf configuration file."},{"q":"When were BIP 39 seed phrases introduced?","options":["2009","2013","2017","2011"],"answer":1,"explanation":"Seed phrases (BIP 39 mnemonics) only came into existence in 2013. Before that, Bitcoin wallets used different, less user-friendly backup methods."},{"q":"What is the maximum size of a single Bitcoin transaction that nodes will relay?","options":["4 MB","1 MB","100 KB","10 KB"],"answer":2,"explanation":"100 KB is the maximum size of a single transaction that standard Bitcoin nodes will verify and relay across the network."},{"q":"What does the Bitcoin dust limit of 546 satoshis represent?","options":["The floor amount below which wallets automatically consolidate UTXOs","The smallest denomination used in Lightning Network channel balances","The minimum fee required before a transaction broadcasts to the mempool","The minimum amount sendable at 1 sat/byte before node relay rules reject it"],"answer":3,"explanation":"546 satoshis is the dust limit — the smallest amount you can send at 1 sat/byte per standard node relay rules. Many wallets use this as their default dust threshold."},{"q":"What is the maximum difficulty adjustment allowed in a single Bitcoin difficulty epoch?","options":["+300% upward or -75% downward","+100% or -50%","+50% or -25%","+1000% or -90%"],"answer":0,"explanation":"Bitcoin's difficulty adjustment is capped: it can increase by at most 300% (4x) or decrease by at most 75% (to 1/4) in a single 2016-block epoch — preventing runaway swings."},{"q":"How many rules does a Bitcoin miner check when validating a single transaction and block?","options":["3–5 rules","30–40 rules each","100+ rules","1 main rule"],"answer":1,"explanation":"When miners validate transactions, they check 30–40 individual rules for each transaction and another 30–40 rules for the block as a whole."},{"q":"Which Bitcoin address format starts with 'bc1p'?","options":["Legacy P2PKH","SegWit v0 (native segwit)","Taproot (SegWit v1)","P2SH wrapped SegWit"],"answer":2,"explanation":"Taproot addresses start with bc1p — Taproot is SegWit version 1. SegWit version 0 addresses start with bc1q (the 'q' standing for version 0, since coders start counting at 0)."},{"q":"Under what conditions will a Bitcoin node reject a block header timestamp?","options":["If the timestamp doesn't match the previous block exactly","If it's older than 10 minutes","If it's in a different time zone than the majority of nodes","If it's more than 2 hours in the future according to the node's clock"],"answer":3,"explanation":"Full nodes will not accept blocks with headers timestamped more than two hours in the future. Block timestamps must also be greater than the median of the previous 11 blocks."},{"q":"On August 15, 2010, a bug in Bitcoin created 184 billion BTC in a single transaction. What happened?","options":["The block was discovered, flagged, and the chain was rolled back in the largest reorg in Bitcoin history (53 blocks)","Satoshi remotely invalidated the extra coins using a developer admin key embedded in the original code","All extra coins were automatically routed to a known burn address encoded in Bitcoin's genesis parameters","Miners voted over several days to orphan the block, but the extra coins remained as an unclaimed supply anomaly"],"answer":0,"explanation":"The value overflow bug in block 74,638 created 184,467,440,737 BTC. Within hours, developers patched the code and the community reorganized the chain — a 53-block reorg, still the largest in Bitcoin history."},{"q":"There is a known bug in Bitcoin that will cause the chain to halt in what year if not fixed?","options":["2140","2106","2999","2050"],"answer":1,"explanation":"An overflow bug in Bitcoin's timestamp handling will cause the chain to halt in the year 2106. It's only fixable through a hard fork — something the community has plenty of time to plan."},{"q":"How many halvings are coded into Bitcoin's source code, even though new supply hits zero after just 33?","options":["21 halvings","33 halvings","64 halvings","100 halvings"],"answer":2,"explanation":"Bitcoin's source code technically encodes 64 halvings, even though the block reward effectively reaches 0 BTC after the 33rd halving. The extra 31 halvings are essentially vestigial code."},{"q":"The first widely noted commercial Bitcoin ASICs shipped when?","options":["2017, bundled with the SegWit release","2012, as the Butterfly Labs Jalapeno","2009, on Satoshi's laptop CPU","Early 2013, starting with Avalon"],"answer":3,"explanation":"Avalon delivered early in 2013. ASICMiner followed. Butterfly Labs shipped the Jalapeno later in 2013. CPU and GPU mining had already been the earlier eras."},{"q":"A 2007 Intel Core 2 Extreme CPU had enough power to solo mine what portion of early Bitcoin?","options":["All of the Bitcoin mined in 2009","Less than 1% of 2009 Bitcoin","All Bitcoin mined in the first 4 years","Only the genesis block"],"answer":0,"explanation":"A 2007 Intel Core 2 Extreme would have been able to solo mine all of the Bitcoin mined in the entire year of 2009 — showing how low the early difficulty was."},{"q":"Approximately how many calories of energy does it take to create 1 Bitcoin?","options":["1,000 calories","314 billion calories","1 million calories","100 billion calories"],"answer":1,"explanation":"1 Bitcoin takes approximately 314 billion calories (or 1,001 billion Joules) of energy to create — a reflection of Bitcoin's proof-of-work security model."},{"q":"Approximately what percentage of Bitcoin's total supply will have been mined by 2035?","options":["75%","50%","99%","90%"],"answer":2,"explanation":"By approximately 2035, around 99% of all Bitcoin will have been mined. The last Bitcoin won't be mined until around the year 2140 due to the halving schedule."},{"q":"How many posts did Satoshi Nakamoto make on the BitcoinTalk forums?","options":["100 posts","21 posts","10,000 posts","575 posts"],"answer":3,"explanation":"Satoshi's BitcoinTalk profile shows 575 posts; his last forum post was Dec 12, 2010."},{"q":"How many known Bitcoin addresses does Satoshi Nakamoto have?","options":["Over 22,000 addresses","1 address","21 addresses","100 addresses"],"answer":0,"explanation":"Satoshi had at least 22,000 documented addresses and likely never reused a single one — demonstrating early and consistent privacy hygiene."},{"q":"What does 'Satoshi' mean in Japanese?","options":["Digital money, derived from the Japanese word for electronic coin","Awakening to truth, related to the Sanskrit word 'Sat'","Hidden identity, a Japanese phrase for anonymous creator","Sound foundation, from the Japanese architectural term for base structure"],"answer":1,"explanation":"Satoshi is a Japanese version of 'Satori' (awakening to truth), itself based on the Sanskrit word 'Sat' meaning truth or being. A fitting name for Bitcoin's creator."},{"q":"bitcoin.org was registered on which date, before the whitepaper?","options":["January 3, 2009","October 31, 2008","August 18, 2008","January 12, 2009"],"answer":2,"explanation":"Public registration history dates bitcoin.org to August 18, 2008. The whitepaper followed on October 31, 2008, and the genesis block on January 3, 2009."},{"q":"What was the pre-release Bitcoin block time before Satoshi changed it to 10 minutes?","options":["30 minutes","5 minutes","1 minute","15 minutes"],"answer":3,"explanation":"The 2008 pre-release version of Bitcoin had 15-minute block times and a difficulty adjustment every 30 days. Satoshi changed both to 10-minute blocks and a 2-week adjustment before the January 2009 launch."},{"q":"What is the approximate probability of randomly guessing someone's Bitcoin private key?","options":["Roughly the same as winning Powerball 7 times in a row","About 1 in 1 million","About 1 in 1 billion","The same as guessing a random 6-digit PIN"],"answer":0,"explanation":"The chance of guessing a Bitcoin private key is astronomically small — roughly equivalent to winning the Powerball lottery 7 times consecutively."},{"q":"The chance of a wallet generating an existing seed phrase is comparable to what?","options":["Guessing a random 6-digit pin code on the first try without any hints","Selecting a specific atom from a grain of sand on one of Earth's beaches","Winning the national lottery jackpot twice in back-to-back weekly draws","Correctly predicting the outcome of 40 consecutive fair coin flips in a row"],"answer":1,"explanation":"The chance of generating an already-existing seed phrase is about the same as selecting a particular atom in a grain of sand (43 quintillion atoms per grain) from one of Earth's beaches — effectively impossible."},{"q":"To restore a Bitcoin wallet, how many letters of each seed word do you need at minimum?","options":["Only the first letter","The full word spelled correctly","The first 4 letters of each word","At least 8 letters"],"answer":2,"explanation":"You only need the first 4 letters of each BIP 39 seed word to initiate a restore — the BIP 39 wordlist was designed so no two words share the same first 4 letters."},{"q":"How much more does it cost to spend from a 2-of-3 multisig compared to a single-sig transaction?","options":["2x more","10x more","The same cost","About 1.5x more"],"answer":3,"explanation":"It costs approximately 1.5x more to spend from a 2-of-3 multisig wallet than a standard single-signature transaction, due to the extra data required for multiple signatures."},{"q":"What is the median base fee on the Lightning Network?","options":["1 satoshi","1,000 satoshis","0 satoshis","100 satoshis"],"answer":0,"explanation":"The median fee rate on the Lightning Network is a base fee of 1 satoshi plus a very small proportional fee rate — making Lightning payments nearly free for everyday amounts."},{"q":"Using SegWit, what is the theoretical maximum block size Bitcoin could scale to with just a soft fork?","options":["4 MB","64 MB","8 MB","2 MB"],"answer":1,"explanation":"With the SegWit upgrade already in place, Bitcoin's block size could technically be increased to 64 MB through just a soft fork — though the community favors keeping blocks small to preserve decentralization."},{"q":"In what year did Bitcoin have no price at all?","options":["2008, before launch","2010, after Pizza Day","For the first ~10 months after launch (2009)","Bitcoin always had a price"],"answer":2,"explanation":"Bitcoin had no price for approximately the first 10 months after its January 2009 launch. The first recorded price didn't appear until late 2009, when Satoshi himself made an early exchange."},{"q":"What was notable about the Overstock.com Bitcoin milestone in 2014?","options":["It was the first company to pay employee salaries in Bitcoin","It was the first company to put Bitcoin on its balance sheet","It launched the first Bitcoin ETF","It was one of the first major national retailers to accept Bitcoin as payment"],"answer":3,"explanation":"Overstock.com became one of the first major national retailers to begin accepting Bitcoin as payment in 2014 — a milestone for mainstream Bitcoin commerce."},{"q":"What is the Bitcoin whitepaper encoded in on the blockchain?","options":["Block 230,009","Block 1 (genesis)","Block 21,000","Block 666,666"],"answer":0,"explanation":"Bitcoin's original whitepaper is encoded in block 230,009 — a piece of Bitcoin history permanently inscribed on the timechain itself."},{"q":"A difficulty retarget compares the last 2,016 blocks with a target span of:","options":["210,000 blocks, which is a halving","1,209,600 seconds, which is two weeks","600 seconds, which is one block","Four years, which is one era"],"answer":1,"explanation":"2,016 blocks times 10 minutes is 1,209,600 seconds. If the epoch was faster, difficulty rises, and if it was slower, difficulty falls, clamped to a factor of four."},{"q":"In Bitcoin lore, 2,016 (the difficulty epoch length) is the semordnilap of which famous Executive Order?","options":["Executive Order 6,210, the first banking holiday decree","Executive Order 9066, which authorized Japanese internment","Executive Order 6102, which forced Americans to sell their gold to the Federal Reserve","Executive Order 2016, creating the Federal Open Market Committee"],"answer":2,"explanation":"Bitcoin difficulty adjusts every 2,016 blocks — the semordnilap (reverse) of 6,102, the Executive Order that forced Americans to hand over gold under threat of imprisonment."},{"q":"By early 2025, James Howells's landfill excavation case stood where?","options":["A miner had rewritten that history","The coins had been spent on chain","The drive had been returned by the council","A court had refused to force the dig"],"answer":3,"explanation":"Howells discarded a drive tied to about 7,500 BTC. In early 2025 a court declined to order an excavation. The coins have not moved. The legal fight to dig was not still open in the way earlier stories said."},{"q":"Bitcoin's original source code contained the beginning of what unexpected feature Satoshi never finished?","options":["A virtual poker game","An in-wallet chat system","A Bitcoin-based email client","A price ticker with live exchange rates"],"answer":0,"explanation":"The original Bitcoin code includes the beginnings of a virtual poker game that Satoshi is believed to have started but never finished — a fascinating Easter egg in early Bitcoin history."},{"q":"In block 124,724, what happened to permanently remove 1 satoshi from Bitcoin's supply?","options":["Satoshi intentionally burned exactly 1 satoshi from that block as a cryptographic proof-of-burn timestamp signature","Solo miner midnightmagic produced 49.99999999 BTC instead of 50, permanently removing 1 satoshi from Bitcoin's supply","A fee rounding error in the transaction validation engine caused exactly 1 satoshi to be double-counted and voided","A competing miner submitted an alternative block at the same height that orphaned 1 satoshi through a chain split"],"answer":1,"explanation":"User midnightmagic solo mined block 124,724 and produced 49.99999999 BTC instead of 50 — because the block subsidy is calculated by block height, not remaining supply. That 1 sat is gone forever, slightly reducing the total supply from 21 million."},{"q":"What happened to Bitcoin's network on the two occasions it went down in its history?","options":["Once for 1 hour during the first halving and once for 2 hours during SegWit activation","Once for 24 hours due to a DDoS attack and once for 48 hours due to a mining bug","Once for 8h 27m due to the value overflow bug (2010) and once for 6h 20m due to a database fork (2013)","It has never gone down — Bitcoin has 100% uptime"],"answer":2,"explanation":"Bitcoin has experienced two notable outages: the 2010 value overflow incident (8h 27m) and a 2013 database compatibility issue (6h 20m). Both were resolved through community consensus to roll back blocks."},{"q":"Hal Finney created a video game in 1982 — what was it called?","options":["Hashrate Hero","Bitcoin Quest","Cypherpunk Chronicles","The Adventures of Tron"],"answer":3,"explanation":"Before becoming one of Bitcoin's earliest contributors, Hal Finney created The Adventures of Tron in 1982 — a game for the Atari 2600. Hal also wrote about NFT-like concepts in 1993, decades before they became mainstream."},{"q":"The 1991 video game Space Quest IV featured a currency that eerily resembled what?","options":["Bitcoin's ₿ symbol","The Ethereum diamond logo","The US dollar sign","A gold coin icon"],"answer":0,"explanation":"Space Quest IV: Roger Wilco and the Time Rippers (1991) featured a currency called the 'Buckazoid' — with a symbol strikingly similar to Bitcoin's ₿ logo, more than a decade before Bitcoin existed."},{"q":"The 2024 COPA judgment in the UK High Court found Craig Wright:","options":["Holds the genesis private key","Is not Satoshi Nakamoto","Wrote Hashcash in 1997","Mined block 170 to Hal Finney"],"answer":1,"explanation":"Mr Justice Mellor's 2024 judgment in the COPA case found that Craig Wright is not Satoshi. The ruling does not say who Satoshi was."},{"q":"What is GPM J1839-10, the object some jokes connect to Bitcoin?","options":["It emits radio waves in patterns matching Bitcoin's block time","It was named after Satoshi Nakamoto by an astronomer","A radio source with a ~21-minute period, seen in archives back to 1988 — any Bitcoin link is a joke","It was discovered on October 31, the day the whitepaper was published"],"answer":2,"explanation":"GPM J1839-10 (Hurley-Walker et al., Nature) is a long-period radio transient with a ~1,318 s period. It is not a star that blinks, and the \"Star of Satoshi-hem\" nickname is not a documented astronomical name."},{"q":"A Bitcoin nLockTime of 500 million or more is read as what?","options":["A Lightning channel capacity","A block height about 9,000 years out","A dollar price target","A Unix timestamp, which overflows in 2106"],"answer":3,"explanation":"Values below 500,000,000 are block heights. Values at or above that are Unix times. The timestamp form runs into the year 2106 because the field is 32 bits. The multi-thousand-year figure belongs to height mode, not to the timestamp."},{"q":"The Patoshi pattern in early blocks is best described as:","options":["A research estimate, not a confession by Satoshi","A signed message spending the genesis coins","A court finding that names the miner","A hard-coded list of 21 million addresses"],"answer":0,"explanation":"Researcher Sergio Lerner described a mining pattern in the earliest blocks and estimated on the order of a million bitcoin. It is an analysis, not a message from Satoshi admitting ownership."},{"q":"How many approximately 300–400 byte transactions fit into a 1 MB Bitcoin block?","options":["100 transactions","3,000–4,000 transactions","10,000 transactions","1,000 transactions"],"answer":1,"explanation":"A Bitcoin transaction is typically 300–400 bytes. With 1,000,000 bytes in a megabyte, a 1 MB base block can fit roughly 3,000–4,000 standard transactions."},{"q":"What is the average number of transactions per second Bitcoin has achieved across its lifetime?","options":["Exactly 7 TPS (by design)","Over 1,000 TPS","Fewer than 10 TPS on the base layer","About 100 TPS with SegWit"],"answer":2,"explanation":"Bitcoin's base layer handles roughly 3–7 transactions per second on average. The Lightning Network, by contrast, can process millions of transactions per second off-chain."},{"q":"Where is an obituary for cypherpunk Len Sassaman permanently stored?","options":["In the Bitcoin Core repository README file","In the Bitcoin whitepaper's references section","In block 0 alongside the genesis block headline","Embedded in every Bitcoin node as a transaction on the timechain"],"answer":3,"explanation":"An obituary for Len Sassaman — a cypherpunk who had direct impact on Bitcoin's creation — is embedded on the Bitcoin timechain and thus stored in every full node. Many believe he may have been Satoshi Nakamoto."},{"q":"How many halvings align between Bitcoin's halving cycle (every 210,000 blocks) and its difficulty epoch (every 2,016 blocks)?","options":["Every 1,260,000th block (every ~24 years)","Every block — they always align","Every 21,000th block","They never align precisely"],"answer":0,"explanation":"Bitcoin halvings (every 210,000 blocks) and difficulty epochs (every 2,016 blocks) align every 1,260,000th block — approximately every 24 years. The math: LCM(210,000, 2,016) = 1,260,000."},{"q":"What was the Bitaxe solo miner's estimated probability of finding a block in July 2024?","options":["1 in 10 days","1 in 3,500 years (which it actually did)","1 in 1,000 years","1 in 21 million"],"answer":1,"explanation":"In July 2024, a Bitaxe home miner with just 3 TH/s successfully found a Bitcoin block — an event with roughly a 1-in-3,500-year statistical probability. One of Bitcoin's most celebrated solo mining moments."},{"q":"Who wrote the line \"Cypherpunks write code\"?","options":["Satoshi Nakamoto, in the Bitcoin whitepaper","Tim May, in the Crypto Anarchist Manifesto","Eric Hughes, in A Cypherpunk's Manifesto (1993)","Phil Zimmermann, in the PGP user's guide"],"answer":2,"explanation":"Eric Hughes published A Cypherpunk's Manifesto on March 9, 1993. The short line \"Cypherpunks write code\" is in that essay."},{"q":"Which sentence opens A Cypherpunk's Manifesto?","options":["Banks must be trusted not to debase the currency","A purely peer-to-peer version of electronic cash","Trusted third parties are security holes","Privacy is necessary for an open society in the electronic age"],"answer":3,"explanation":"That is the opening sentence of Eric Hughes's manifesto, March 9, 1993."},{"q":"Who wrote \"Privacy is the power to selectively reveal oneself to the world\"?","options":["Eric Hughes, in the 1993 cypherpunk manifesto","Nick Szabo, in the Bit Gold essay","Adam Back, in the Hashcash paper","Wei Dai, in the b-money proposal"],"answer":0,"explanation":"The line is from Eric Hughes, A Cypherpunk's Manifesto, March 9, 1993."},{"q":"Hughes wrote that privacy in an open society requires what kind of payment tool?","options":["A central bank settlement window","Anonymous transaction systems","Mandatory identity on every payment","A government-run digital dollar"],"answer":1,"explanation":"A Cypherpunk's Manifesto (March 9, 1993) says privacy in an open society requires anonymous transaction systems."},{"q":"Tim May's 1988 manifesto says a specter haunting the modern world is the specter of what?","options":["Quantum computers","Paper banknotes","Crypto anarchy","Central planning"],"answer":2,"explanation":"The Crypto Anarchist Manifesto, written by Timothy C. May in 1988, opens with that line. It later circulated on the cypherpunks list."},{"q":"Who wrote the Crypto Anarchist Manifesto?","options":["David Chaum","Eric Hughes","John Gilmore","Timothy C. May"],"answer":3,"explanation":"Timothy C. May wrote it in 1988. It is a different text from Eric Hughes's 1993 Cypherpunk's Manifesto."},{"q":"Which three people are credited with starting the cypherpunks mailing list in 1992?","options":["Eric Hughes, Tim May, and John Gilmore","Satoshi, Hal Finney, and Adam Back","Szabo, Dai, and Chaum","Zimmermann, Assange, and Bernstein"],"answer":0,"explanation":"Hughes, May, and Gilmore launched the cypherpunks list in 1992. John Gilmore was also a cofounder of the Electronic Frontier Foundation."},{"q":"Wei Dai's 1998 note b-money opens by saying he is fascinated by whose ideas?","options":["Satoshi's whitepaper","Tim May's crypto-anarchy","Hayek's commodity basket","Keynes's deficit spending"],"answer":1,"explanation":"The b-money text (1998) begins: \"I am fascinated by Tim May's crypto-anarchy.\" Satoshi later cited b-money."},{"q":"What did Adam Back propose in 1997 that Satoshi cited in the whitepaper?","options":["A proof-of-stake voting coin","A federated Chaumian bank","Hashcash, a proof-of-work cost for abuse","A government identity ledger"],"answer":2,"explanation":"Hashcash (1997) makes an email or request costly to spam. The Bitcoin whitepaper lists it in the references."},{"q":"What is the title of Nick Szabo's warning about middlemen?","options":["Privacy is a setting in an app","Code is law for every contract","Cypherpunks write production code","Trusted third parties are security holes"],"answer":3,"explanation":"Szabo used that sentence as the title of a 2001 essay. It is a design warning, not a claim that every intermediary is useless."},{"q":"What did Nick Szabo call the scarce digital collectible he proposed in 1998 and wrote up in 2005?","options":["Bit gold","b-money","Hashcash","Ecash"],"answer":0,"explanation":"Szabo proposed bit gold in 1998. The essay \"Bit gold\" was posted in December 2005. It was a design, not a launched chain, and Satoshi did not say it was Bitcoin."},{"q":"On the P2P Foundation forum, February 11, 2009, Satoshi said the root problem with ordinary currency is what?","options":["A shortage of vault space for coins","All the trust required to make it work","That miners set the tax rate","That gold is too heavy to ship"],"answer":1,"explanation":"The post is titled \"Bitcoin open source implementation of P2P currency\" (P2P Foundation forum, February 11, 2009). It says: \"The root problem with conventional currency is all the trust that's required to make it work.\" Source: https://satoshi.nakamotoinstitute.org/posts/p2pfoundation/1/ . BitcoinTalk did not exist until November 2009."},{"q":"In that same February 11, 2009 post, Satoshi says the central bank must be trusted not to do what?","options":["Ban the use of paper cash","Publish every account balance","Debase the currency","Shut down every local bank"],"answer":2,"explanation":"He wrote that the central bank must be trusted not to debase the currency, and that fiat history is full of breaches of that trust."},{"q":"Satoshi wrote that banks lend deposits out \"in waves of credit bubbles\" with barely what in reserve?","options":["A ten-year lockup","A full gold bar per note","A voter referendum","A fraction"],"answer":3,"explanation":"The same February 11, 2009 P2P Foundation post says banks \"lend it out in waves of credit bubbles with barely a fraction in reserve.\" Source: https://satoshi.nakamotoinstitute.org/posts/p2pfoundation/1/ ."},{"q":"Who wrote \"If you don't believe me or don't get it, I don't have time to try to convince you, sorry\"?","options":["Satoshi, on BitcoinTalk, July 29, 2010","Hal Finney, on Twitter, January 2009","Adam Back, in the Hashcash paper","Nick Szabo, in the Bit Gold post"],"answer":0,"explanation":"That brusque line is Satoshi's BitcoinTalk reply on July 29, 2010."},{"q":"Where did Satoshi write that WikiLeaks had \"kicked the hornet's nest\"?","options":["The genesis block coinbase","BitcoinTalk, December 11, 2010","An email to the US Treasury","The whitepaper conclusion"],"answer":1,"explanation":"On December 11, 2010 he wrote: \"WikiLeaks has kicked the hornet's nest, and the swarm is headed towards us.\""},{"q":"Before BitcoinTalk, where was Satoshi's project forum hosted?","options":["A Usenet newsgroup","The P2P Foundation forum","SourceForge","A Bitcoin Wiki talk page"],"answer":2,"explanation":"The Bitcoin Wiki says that before BitcoinTalk, Satoshi used a SourceForge forum, which is now lost. The board later moved to bitcoin.org and then to bitcointalk.org, founded November 22, 2009. Source: https://en.bitcoin.it/wiki/BitcoinTalk"},{"q":"Laszlo Hanyecz's May 18, 2010 BitcoinTalk post offered bitcoin for what?","options":["A one-way plane ticket","A used car in California","A domain name and a server","A couple of pizzas, about two large ones"],"answer":3,"explanation":"He wrote: \"I'll pay 10,000 bitcoins for a couple of pizzas.. like maybe 2 large ones so I have some left over for the next day.\" The pizzas arrived on May 22."},{"q":"The whitepaper abstract says peer-to-peer electronic cash would send payments without going through what?","options":["A financial institution","A digital signature","A proof-of-work puzzle","A timestamp server"],"answer":0,"explanation":"The first sentence of the abstract (October 31, 2008) says payments could go \"without going through a financial institution.\""},{"q":"The whitepaper's last paragraph says the system handles transactions without relying on what?","options":["Electricity","Trust","Public keys","Block rewards"],"answer":1,"explanation":"The conclusion says: \"We have proposed a system for electronic transactions without relying on trust.\""},{"q":"David Chaum's 1982 paper introduced which tool for private digital payments?","options":["Merkle trees","Proof of work","Blind signatures","Schnorr signatures"],"answer":2,"explanation":"The paper is \"Blind Signatures for Untraceable Payments\" (1982). The signer learns the amount was approved without learning who spent the note."},{"q":"What did Phil Zimmermann release in 1991?","options":["The Signal protocol","The Tor browser","The Bitcoin client","PGP, Pretty Good Privacy"],"answer":3,"explanation":"PGP let people encrypt email. US authorities investigated Zimmermann over export rules. He was not charged."},{"q":"Which case is the usual US precedent that software code can be protected speech?","options":["Bernstein v. United States","A conviction of Phil Zimmermann","The Mt. Gox criminal case","SEC v. Ripple Labs"],"answer":0,"explanation":"Daniel Bernstein's lawsuit, decided by the Ninth Circuit in the 1990s, is the precedent. Zimmermann's PGP case never became a conviction."},{"q":"Who is widely credited with coining the word cypherpunk?","options":["Satoshi Nakamoto","Jude Milhon, known as St. Jude","Adam Back","Hal Finney"],"answer":1,"explanation":"Jude Milhon, a hacker and writer also called St. Jude, is widely credited with the word. The 1992 mailing list then made it famous."},{"q":"John Gilmore, a cypherpunks cofounder, also cofounded which organization?","options":["The Federal Reserve","The Bitcoin Foundation","The Electronic Frontier Foundation","The World Bank"],"answer":2,"explanation":"Gilmore cofounded the EFF and was one of the three people behind the 1992 cypherpunks list."},{"q":"Hal Finney's 2004 project RPOW stood for what?","options":["Relay Protocol of Witnesses","Random Proof of Wealth","Root Public Owning Wallet","Reusable Proofs of Work"],"answer":3,"explanation":"RPOW let a proof-of-work token be passed along without redoing the work. Finney later ran one of the first Bitcoin nodes."},{"q":"Which mailing list received the Bitcoin whitepaper on October 31, 2008?","options":["The Cryptography list at metzdowd.com","The cypherpunks list from 1992","A private email to the SEC","The Linux kernel mailing list"],"answer":0,"explanation":"Satoshi posted the paper to the Cryptography mailing list hosted at metzdowd.com, not to the old cypherpunks list."},{"q":"What address did Satoshi use on the whitepaper announcement?","options":["satoshi@bitcoin.org","satoshi@vistomail.com","nakamoto@gmail.com","admin@cryptography.org"],"answer":1,"explanation":"The October 31, 2008 announcement to the Cryptography list was sent from satoshi@vistomail.com."},{"q":"When did Satoshi open the BitcoinTalk forum?","options":["February 11, 2009","October 31, 2008","November 22, 2009","April 23, 2011"],"answer":2,"explanation":"The Bitcoin Wiki records BitcoinTalk as founded on November 22, 2009 by Satoshi Nakamoto. The February 11, 2009 project announcement was on the P2P Foundation forum, before this board existed. Source: https://en.bitcoin.it/wiki/BitcoinTalk"},{"q":"Satoshi's genesis coinbase quotes which paper and date?","options":["The Economist, 31/Oct/2008","The Wall Street Journal, 15/Sep/2008","The New York Times, 09/Jan/2009","The Times, 03/Jan/2009"],"answer":3,"explanation":"The coinbase text is \"The Times 03/Jan/2009 Chancellor on brink of second bailout for banks.\" It timestamps the block and comments on the bank bailouts."},{"q":"Who received 10 BTC from Satoshi in block 170?","options":["Hal Finney, on January 12, 2009","Nick Szabo, on January 3, 2009","Adam Back, on October 31, 2008","Wei Dai, on August 18, 2008"],"answer":0,"explanation":"Block 170, the first block with a normal transfer, is timestamped January 12, 2009 (UTC). Finney's \"Running bitcoin\" tweet was January 11."},{"q":"About when were Satoshi's last public BitcoinTalk posts?","options":["January 2009","December 2010","The 2012 halving","March 2014"],"answer":1,"explanation":"The \"hornet's nest\" post is December 11, 2010, among the last forum messages. The later \"moved on\" note was a private email to Mike Hearn in April 2011."},{"q":"Who did Satoshi leave in charge of the Bitcoin code when he stepped back?","options":["A corporate foundation","Hal Finney alone","Gavin Andresen","The US Treasury"],"answer":2,"explanation":"Satoshi gave Gavin Andresen commit access and later told Mike Hearn the project was in Gavin's hands. Andresen was a maintainer, not an owner of the rules."},{"q":"Who wrote the 2024 COPA judgment that found Craig Wright is not Satoshi?","options":["Satoshi Nakamoto","The SEC chair","A California jury","Mr Justice Mellor"],"answer":3,"explanation":"Mr Justice Mellor of the High Court of England and Wales wrote the 2024 COPA judgment. It found that Craig Wright is not Satoshi. It does not say who Satoshi was."},{"q":"What did Dorian Nakamoto say after a 2014 magazine named him as Satoshi?","options":["He denied creating Bitcoin","He published the genesis key","He claimed the pizza payment","He joined Bitcoin Core"],"answer":0,"explanation":"Newsweek's March 2014 profile pointed at Dorian Prentice Satoshi Nakamoto. He said he was not the Bitcoin author."},{"q":"The Patoshi mining-pattern research estimates Satoshi's early coins at about what scale?","options":["Exactly 21 million bitcoin","On the order of one million bitcoin","Only the 50 BTC genesis reward","Zero, because Satoshi never mined"],"answer":1,"explanation":"Sergio Lerner's Patoshi studies group early blocks by nonce patterns. The figure is an estimate of coins that have not moved as a group, not a confession."},{"q":"Who bought the pizzas in Laszlo Hanyecz's May 2010 bitcoin offer?","options":["Satoshi Nakamoto, in Japan","A London restaurant that called Laszlo","Jeremy Sturdivant (jercos), in the United States","Hal Finney, from a hospital"],"answer":2,"explanation":"Forum user jercos, Jeremy Sturdivant, bought the pizzas. Contemporary accounts place him in the United States. A London phone call is not established. The offer is the May 18, 2010 BitcoinTalk post."},{"q":"Which early Bitcoin developer used the forum name Sirius?","options":["Adam Back","Hal Finney","Nick Szabo","Martti Malmi"],"answer":3,"explanation":"Martti Malmi (Sirius) was an early contributor who worked on bitcoin.org and the software while Satoshi was still active."},{"q":"What is the title printed on the Bitcoin whitepaper?","options":["Bitcoin: A Peer-to-Peer Electronic Cash System","Bitcoin: A Peer-to-Peer Electronic Gold System","Bit Gold: Digital Collectibles Without Banks","b-money: Two Protocols for Trade"],"answer":0,"explanation":"That is the title on the October 31, 2008 paper signed Satoshi Nakamoto."},{"q":"Whitepaper section 8 describes which idea?","options":["The 21 million supply cap","Simplified payment verification","A central mint run by miners","Anonymous mining pools"],"answer":1,"explanation":"Section 8 is Simplified Payment Verification: checking a payment with headers and a Merkle branch instead of every old transaction."},{"q":"Whitepaper section 4 is about which mechanism?","options":["Proof of stake voting","A board of governors","Proof of work","A trusted timestamp company"],"answer":2,"explanation":"Section 4, Proof-of-Work, describes scanning for a hash below a target and chaining that work."},{"q":"Which timestamp papers does the whitepaper cite alongside Hashcash and b-money?","options":["A 2016 Lightning paper","The SEC's 2017 token report","The IMF's 2025 country review","Haber and Stornetta's timestamp work"],"answer":3,"explanation":"The references include Stuart Haber and W. Scott Stornetta on time-stamping a document, plus Back's Hashcash and Wei Dai's b-money."},{"q":"What does the whitepaper say a merchant can do after some blocks are buried on top?","options":["Treat older payments as practically irreversible","Reverse a payment with a phone call","Ask Satoshi to edit the ledger","Inflate the supply to refund a buyer"],"answer":0,"explanation":"The paper argues that as more proof of work is piled on, reversing a payment gets more expensive. It does not promise a legal refund."},{"q":"In his March 2013 \"Bitcoin and me\" post, Hal Finney described living with which illness?","options":["A mining-pool bankruptcy","ALS, amyotrophic lateral sclerosis","A lost laptop password","A 2011 exchange hack"],"answer":1,"explanation":"Hal Finney's BitcoinTalk post \"Bitcoin and me\" (March 2013) describes living with ALS. Source: https://bitcointalk.org/index.php?topic=155054.0 . He died on August 28, 2014."},{"q":"Which cypherpunk cryptographer's obituary was encoded into the blockchain after his death in 2011?","options":["David Chaum","Phil Zimmermann","Len Sassaman","Tim May"],"answer":2,"explanation":"An obituary for Len Sassaman, a cypherpunk and remailer developer who died in July 2011, was written into the chain as a memorial. That does not identify him as Satoshi."},{"q":"DigiCash, David Chaum's company for electronic cash, was founded in which period?","options":["During the 2024 ETF launch","In January 2009","After the 2017 bull market","Around 1990"],"answer":3,"explanation":"Chaum founded DigiCash around 1990 to commercialize ecash. The company later failed. Bitcoin removed the company from the design."},{"q":"Zooko's triangle says a naming system struggles to be human-readable, secure, and what at once?","options":["Decentralized","Inflationary","Custodial","Pegged to gold"],"answer":0,"explanation":"Zooko Wilcox-O'Hearn described the tradeoff: pet names that are easy, secure, and globally consistent usually give one up. Bitcoin addresses skip the human-readable corner."},{"q":"Who maintains Bitcoin Knots, the full node that keeps stricter default relay policy?","options":["Satoshi Nakamoto","Luke Dashjr","The SEC","A mining-pool committee"],"answer":1,"explanation":"Luke Dashjr maintains Bitcoin Knots. It follows Bitcoin's consensus rules and differs mainly in policy defaults, including the OP_RETURN size it will relay."},{"q":"Bitcoin Core version 30, released in October 2025, changed which default?","options":["The 10-minute block target","The 21 million supply cap","The OP_RETURN relay limit, up to about 100 KB","The proof-of-work hash function"],"answer":2,"explanation":"Core v30 raised the default datacarrier size from 80 bytes to on the order of 100 KB. That is relay policy, not a consensus rule. Knots users objected."},{"q":"What did the March 2025 US executive order create?","options":["A federal exchange run by the Fed","A ban on self-custody wallets","A new bitcoin supply schedule","A Strategic Bitcoin Reserve"],"answer":3,"explanation":"The March 2025 order set up a US Strategic Bitcoin Reserve, capitalized with bitcoin the government already held from forfeiture, and a separate stockpile for other coins."},{"q":"Which town's grassroots project is called Bitcoin Beach?","options":["El Zonte, El Salvador","Geneva, Switzerland","London, England","Miami, Florida"],"answer":0,"explanation":"Bitcoin Beach is the grassroots project in El Zonte, El Salvador. People there used bitcoin for local trade before the 2021 national law."},{"q":"When did the Central African Republic repeal its bitcoin legal-tender law?","options":["In 2009","In 2023","In June 2021","It never passed a law"],"answer":1,"explanation":"The CAR adopted a bitcoin legal-tender law in 2022 and repealed it in 2023. El Salvador's 2021 law was the first."},{"q":"US spot bitcoin ETFs were approved and began trading when?","options":["The 2012 halving","October 31, 2008","Approved January 10, 2024; trading January 11","March 2025, with the reserve order"],"answer":2,"explanation":"The SEC approved several spot bitcoin ETFs on January 10, 2024. They listed the next day. An ETF share is a claim on the fund, not a private key."},{"q":"MicroStrategy announced its bitcoin treasury policy when, and what is the company's later name?","options":["The 2017 fork; it became Bitcoin Cash","January 2009; it was always Strategy","May 22, 2010; it was Pizza Corp","August 2020; it later rebranded as Strategy"],"answer":3,"explanation":"Michael Saylor's firm announced bitcoin purchases in August 2020. In 2025 the company rebranded from MicroStrategy to Strategy. Holdings change, so a coin count goes stale fast."},{"q":"What happened to Block's TBD identity project?","options":["It was shut down in late 2024","It became the US digital dollar","It merged into Bitcoin Core","It replaced Cash App"],"answer":0,"explanation":"TBD was Block's decentralized-identity effort, including the Web5 pitch. Block shut it down in late 2024. Cash App, Bitkey, and Proto mining gear continued."},{"q":"Samourai Wallet's Whirlpool coordinator stopped when?","options":["January 2009, with the genesis block","April 2024, after US charges against the founders","The day SegWit activated","It is still the default mixer"],"answer":1,"explanation":"US authorities charged the Samourai founders in April 2024 and the Whirlpool coordinator shut down. The founders were later convicted. Mixing did not become illegal as a concept, but that service ended."},{"q":"What did Wasabi Wallet's company zkSNACKs do with its coordinator in 2024?","options":["It took over Bitcoin Core releases","It became a US spot ETF","It shut the default coordinator down","It froze the 21 million cap"],"answer":2,"explanation":"zkSNACKs closed its Wasabi CoinJoin coordinator in 2024. The idea of CoinJoin is older: Gregory Maxwell described it in 2013."},{"q":"Mutiny Wallet, a Lightning app, ended when?","options":["It is the only Lightning wallet left","It launched the genesis block","It became the IMF wallet","It shut down in late 2024"],"answer":3,"explanation":"Mutiny shut down in late 2024. Phoenix, Zeus, and other wallets kept working. A shutdown is a reminder that an app is not the Bitcoin network."},{"q":"Blockfolio, a portfolio app later tied to FTX, is in what state?","options":["Defunct since the FTX collapse","The official Bitcoin Core wallet","A 2024 spot ETF ticker","El Salvador's Chivo replacement"],"answer":0,"explanation":"Blockfolio was acquired and folded into the FTX app. It did not survive the 2022 FTX failure as a product people should rely on."},{"q":"China's 2021 mining ban did what to network hashrate?","options":["It deleted the ledger","Hashrate fell, then recovered in other countries","It changed the supply cap","It ended difficulty adjustment"],"answer":1,"explanation":"In May and June 2021 China restricted mining. Hashrate dropped and then returned as machines moved. The difficulty adjustment retargeted the block interval."},{"q":"Nigeria's central bank restricted bank-to-crypto transfers in 2021. What kept bitcoin moving?","options":["A hard fork that banned naira","A government airdrop of new coins","Peer-to-peer trade outside those banks","Closing every Bitcoin node"],"answer":2,"explanation":"The restriction hit banks, not the protocol. People kept trading peer to peer. A later policy shift did not give Nigeria a kill switch for the chain."},{"q":"What happened to Block's TBD project?","options":["It became a required module of Bitcoin Core","It replaced proof of work in 2024","It mined the genesis block","TBD was discontinued in late 2024"],"answer":3,"explanation":"Block discontinued TBD in late 2024. Cash App, Bitkey, and Proto are separate products and were not that shutdown."},{"q":"A Bitaxe is best described as what?","options":["A small open-source home miner, often under about 2 TH/s","A 300 TH/s datacenter machine","A Lightning routing node","A hardware wallet"],"answer":0,"explanation":"Bitaxe boards are open hardware for learning and solo attempts. Common units are around 0.5 to 1.2 TH/s, and a GT-class board is near 2 TH/s, not a general 3 TH/s claim."},{"q":"Cambridge's 2025 mining survey described energy sources how?","options":["One hundred percent coal","A bit over half sustainable if nuclear is included","Zero electricity, only solar myths","A protocol rule requiring green power"],"answer":1,"explanation":"The 2025 Cambridge estimate put sustainable energy, including nuclear, at about 52%, with renewables nearer 43%. Say sustainable or about half, not \"mostly renewable\" as a law."},{"q":"The integer satoshi schedule issues how many sats in total?","options":["100 million sats","Exactly 21,000,000.00000000 BTC with no rounding","2,099,999,997,690,000","An unlimited number of sats"],"answer":2,"explanation":"Halving an integer satoshi subsidy does not land on a perfect 21,000,000 BTC. The consensus sum is 2,099,999,997,690,000 sats, just under 21 million."},{"q":"Gresham's law and Thiers' law differ how?","options":["Both set the block reward","Both say bitcoin must replace the dollar in 2030","Both ban saving","Fixed face value favors bad money; free prices favor good money"],"answer":3,"explanation":"Gresham: if bad and good money have the same legal face value, people spend the bad and hoard the good. Thiers: when prices can adjust, people prefer the better money."},{"q":"What is the Cantillon effect?","options":["New money helps whoever receives it before prices rise","Miners vote on the tax rate","Nodes delete old coins","Fees are always one sat"],"answer":0,"explanation":"Richard Cantillon described how fresh money reaches some people first. They spend before prices adjust. Later recipients face the higher prices."},{"q":"Stock-to-flow is which kind of statement?","options":["A consensus rule in Bitcoin Core","A model of stock divided by yearly flow, not a price promise","A guarantee of next year's price","The difficulty formula"],"answer":1,"explanation":"Stock-to-flow divides the existing stock by new production. PlanB's bitcoin chart was a model. It is not in the protocol and it has missed."},{"q":"IRS Notice 2014-21 says that for US federal tax, bitcoin is treated as what?","options":["A tax-free gift in every case","A foreign currency with no records","Property","A social-security benefit"],"answer":2,"explanation":"Notice 2014-21 says convertible virtual currency is property. Spending it can be a taxable disposal. Other countries differ. This is not tax advice."},{"q":"xkcd comic 538 is the usual picture for which bitcoin risk?","options":["A difficulty retarget","A SHA-256 collision","An ETF share split","A wrench attack: coercion, not a broken hash"],"answer":3,"explanation":"The comic shows a $5 wrench used to force a passphrase. In bitcoin it means physical threats. The defense is operational: multisig, decoys, and not advertising holdings."},{"q":"Putting a raw seed phrase in a will that a court will publish is risky because?","options":["Probate can expose the secret","The chain deletes the coins","Miners refuse inherited coins","BIP39 words expire after death"],"answer":0,"explanation":"A will can say that bitcoin exists and where the instructions are. The seed itself should stay off a document strangers will read. This is not legal advice."},{"q":"Address poisoning tries to trick you into doing what?","options":["Signing a miner's block header","Copying a look-alike address from your history","Raising the block weight limit","Halving the supply early"],"answer":1,"explanation":"An attacker sends a tiny output from an address that looks like yours, hoping you copy it later. Check the whole address on a trusted screen."},{"q":"A support agent who asks for your 12 or 24 words is what?","options":["An ETF transfer agent","A required Bitcoin Core step","A scammer, or a catastrophic mistake","A miner verifying your UTXO"],"answer":2,"explanation":"No real wallet, exchange, or Bitcoin developer needs your seed to \"fix\" an account. Anyone with the words can move the coins."},{"q":"Giveaway posts that say \"send 0.1 BTC and receive 1 BTC back\" are what?","options":["A Core v30 feature","A consensus airdrop","A Lightning routing fee","A classic theft script"],"answer":3,"explanation":"The chain does not double coins you send to a stranger. Those posts impersonate famous people. There is no protocol refund."},{"q":"Blockstream Satellite broadcasts the blockchain as what kind of link?","options":["A one-way satellite downlink, not a mesh radio","A two-way mesh that replaces the internet","A miner-only private network","A Lightning channel to space"],"answer":0,"explanation":"The satellite lets a dish receive block data without ordinary internet. It does not by itself let you send a transaction, and it is not a mesh network."},{"q":"A pruned node is which kind of node?","options":["A miner that skips validation","A full node that deletes old blocks after checking them","A light wallet with no rules","An archival server only"],"answer":1,"explanation":"Pruned mode validates the chain, then throws away old block files. It still enforces the rules. It just cannot serve ancient blocks to peers."},{"q":"An archival node keeps what that a pruned node may drop?","options":["The mining reward schedule","Only the price chart","Old block files, after both have validated","Other people's seeds"],"answer":2,"explanation":"Both can be full nodes. Archival mode stores historical blocks so it can serve them. Pruned mode keeps the UTXO set and recent blocks."},{"q":"How big is a Bitcoin block header?","options":["546 satoshis","1 megabyte","4 million weight units","80 bytes"],"answer":3,"explanation":"Version, previous hash, Merkle root, time, bits, and nonce: 4+32+32+4+4+4 = 80 bytes. The block hash is the hash of that header."},{"q":"Bitcoin hashes the block header with which construction?","options":["SHA-256 applied twice","A single MD5 pass","Scrypt then SHA-1","A password KDF only"],"answer":0,"explanation":"The block hash is SHA-256(SHA-256(header)). Wallets also use hash256 in several places. It is not the same as a key-stretching password hash."},{"q":"The fee of a confirmed transaction is defined as what?","options":["A field the miner must set to 1 sat","Inputs minus outputs, with no separate fee field","A percentage of the dollar price","A tax added by the node operator"],"answer":1,"explanation":"Whatever sats go in and do not come out are the fee. The miner who includes the transaction collects them."},{"q":"Coinbase outputs cannot be spent for how many blocks?","options":["2016 blocks","6 blocks","100 blocks","1 block"],"answer":2,"explanation":"Consensus maturity is 100 blocks. It stops a miner from spending a reward that might still be reorged away."},{"q":"nLockTime values below 500 million are read as what?","options":["A Lightning invoice","A Unix timestamp","A dollar price","A block height"],"answer":3,"explanation":"Below 500,000,000 the field is a block height. At or above that it is a Unix time. Timestamp locktime hits the 2106 limit of a 32-bit time."},{"q":"Block-height locktime can point far beyond 2106 because?","options":["Heights up to 500 million are allowed","The timestamp field has 64 bits","Miners ignore locktime","CLTV was removed"],"answer":0,"explanation":"The famous multi-thousand-year figure is height-based locktime, not the timestamp mode. Timestamp mode ends in 2106."},{"q":"BIP39's English wordlist has how many words, and why do four letters identify one?","options":["12 words, and you need the whole word","2048 words, and no two share the first four letters","1024 words, and the last letter is the checksum","256 words, one per bit of a hash"],"answer":1,"explanation":"The list was built so the first four letters are unique. You still need every word in order, plus any passphrase."},{"q":"A 12-word BIP39 phrase encodes how much entropy, before the checksum?","options":["12 bits","256 bits","128 bits","21 million bits"],"answer":2,"explanation":"Twelve words carry 128 bits of entropy plus a checksum. Twenty-four words carry 256 bits. The checksum is why a random 12-word string usually fails."},{"q":"An optional BIP39 passphrase does what?","options":["It publishes your xpub","It is always the 13th word from the list","It resets the 21 million cap","It derives a different wallet, and it is not a list word"],"answer":3,"explanation":"Any string works, including a blank one. A different passphrase means a different set of keys. Lose it and the words alone open a different, empty wallet."},{"q":"Mainnet bech32 and bech32m addresses start with what?","options":["bc1","1 only","3 only","tb1"],"answer":0,"explanation":"bc1q is typically SegWit v0. bc1p is Taproot. Testnet uses tb1. Legacy P2PKH still starts with 1, and P2SH often starts with 3."},{"q":"BIP86 derivation for single-sig Taproot uses which purpose field?","options":["m/44'/0'/... only","m/86'/0'/...","m/0'/0'/0'","a random path each boot"],"answer":1,"explanation":"BIP44 is the older multi-coin path. BIP84 is native SegWit. BIP86 is the Taproot single-sig path. Your backup should record the path the wallet actually used."},{"q":"BIP152 compact blocks help nodes do what?","options":["Replace proof of work","Raise the weight limit","Send a short sketch so peers rebuild the block","Hide the UTXO set"],"answer":2,"explanation":"Matt Corallo's compact-block design (BIP152) saves bandwidth when peers already have the transactions. It is not a privacy mixer."},{"q":"BIP324 adds what to Bitcoin peer connections?","options":["A 1 MB weight increase","A new supply schedule","A required identity document","An encrypted transport option"],"answer":3,"explanation":"BIP324 is a version-2 P2P transport with encryption. It hides the contents of the connection from a passive network observer. It does not make on-chain history private."},{"q":"Full replace-by-fee means which policy?","options":["An unconfirmed spend can be replaced even without the old signal","A confirmed block can be edited","The fee field can be negative","Miners must accept every double spend"],"answer":0,"explanation":"BIP125 replacement was opt-in via nSequence. Full RBF is the policy of allowing a higher-fee replacement even when the original did not signal. Neither reverses a confirmed payment."},{"q":"Child-pays-for-parent helps when?","options":["You want to rewrite a buried block","A later spend pays a high fee to pull a stuck parent","You need to change the coinbase maturity","You are opening a Lightning channel only"],"answer":1,"explanation":"If you can spend an output of a stuck transaction, a high-fee child can make miners want the whole package. It does not require the original sender to cooperate."},{"q":"A transaction signals BIP125 replaceability when an input's nSequence is below what?","options":["the dust limit of 546","the block height 210,000","0xfffffffe","a dollar fee of one cent"],"answer":2,"explanation":"The transaction signals replaceability, not the miner. Under BIP125, an input with nSequence below 0xfffffffe opts the transaction into replacement. Receivers of zero-confirmation payments should know that."},{"q":"Signet, specified in BIP325, improves on public testnet by doing what?","options":["Freezing coins for a year","Paying real mainnet rewards","Removing signatures","Letting a signer produce orderly test blocks"],"answer":3,"explanation":"Public testnet difficulty can be gamed. Signet blocks are signed so the network can keep a steadier test chain. Regtest is the private one on your own computer."},{"q":"The difficulty change each 2016 blocks is clamped to what factor?","options":["At most 4 times up or 4 times down","At most 10 percent","Exactly zero, the target is fixed","A vote of mining pools"],"answer":0,"explanation":"If blocks came too fast or too slow, the target moves, but not by more than a factor of four in one epoch. That bounds the shock from a hashrate crash or surge."},{"q":"2016 blocks times the 10-minute target equals about how long?","options":["One day","Two weeks","Four years","One hour"],"answer":1,"explanation":"2016 × 10 minutes is 20,160 minutes, which is 14 days. Real epochs vary because block times are random."},{"q":"210,000 blocks at 10 minutes is about how long?","options":["About ten minutes","About two weeks","About four years","About one century"],"answer":2,"explanation":"210,000 × 10 minutes is roughly 3.99 years. That is why halvings land near a four-year rhythm, not on a calendar date written in the code."},{"q":"How many halvings take the subsidy from 50 BTC down to zero sats?","options":["1 halving, already finished","7 halvings, in 2028","64 halvings, all of them still paying coins","33 halvings, around the year 2140"],"answer":3,"explanation":"The subsidy is an integer number of sats. It reaches zero at the 33rd halving. The code's shift count goes further, but the payout is already zero."},{"q":"SegWit activated at which block and approximate date?","options":["Block 481,824, on August 24, 2017","Block 0, on January 3, 2009","Block 709,632, in November 2021","The Bitcoin Cash fork block only"],"answer":0,"explanation":"SegWit locked in during the 2017 signaling period and activated at block 481824. Taproot was a later soft fork, in November 2021."},{"q":"Taproot activated on which date and block?","options":["August 1, 2017, the Cash fork","November 14, 2021, block 709,632","October 31, 2008, the whitepaper","April 20, 2024, the halving"],"answer":1,"explanation":"Taproot (BIPs 340, 341, and 342) activated at block 709632 using Speedy Trial signaling. It added Schnorr signatures and a new output type."},{"q":"BIP340, BIP341, and BIP342 are which upgrade?","options":["The Lightning BOLTs","The block-size hard fork","Schnorr, Taproot, and Tapscript","The ETF approval order"],"answer":2,"explanation":"BIP340 specifies Schnorr signatures on secp256k1. BIP341 is Taproot. BIP342 is Tapscript. Together they were the 2021 soft fork."},{"q":"The Lightning whitepaper was written by whom, and when?","options":["The SEC staff, 2024","Satoshi Nakamoto, 2008","Nick Szabo, 2005","Joseph Poon and Thaddeus Dryja; drafted 2015, final Jan 2016"],"answer":3,"explanation":"Poon and Dryja drafted the Lightning paper in 2015. The final version is January 2016. The BOLT specs came afterward so different teams could interoperate."},{"q":"A classic Lightning channel is locked as what?","options":["A 2-of-2 multisig that both parties update","A custodial balance at a bank","An OP_RETURN message","A miner coinbase"],"answer":0,"explanation":"The common design is a shared 2-of-2 output plus off-chain commitment transactions. Taproot channels exist too. Closing publishes a settlement on chain."},{"q":"Inbound Lightning liquidity means what?","options":["You mined a block","You can receive, because the peer holds spendable balance","You raised the fee filter","You disabled your node"],"answer":1,"explanation":"A channel has a fixed capacity. To receive, the other side needs balance it can push to you. That is why a new channel often starts send-only."},{"q":"HTLC and PTLC differ how?","options":["PTLC removes all timeouts","HTLC is on Ethereum only","HTLC reveals a hash preimage; a PTLC can hide it","HTLC changes the 21 million cap"],"answer":2,"explanation":"Hash-locked contracts can correlate a payment if the same hash appears along a route. Point-timelock contracts use adaptor signatures so that link is weaker."},{"q":"BOLT 12 offers aim to let a receiver do what?","options":["Print new bitcoin","Mine blocks from a phone","Skip on-chain channel opens forever","Reuse a static offer instead of a one-time invoice"],"answer":3,"explanation":"A BOLT 11 invoice is typically single use. BOLT 12 offers are a newer spec for reusable payment requests. Wallet support is uneven, so check the app."},{"q":"A Lightning watchtower exists to do what?","options":["Publish a penalty if a cheat is attempted while you are offline","Custod your seed phrase","Set the dollar price","Replace your full node"],"answer":0,"explanation":"Old Lightning justice transactions punish a peer who broadcasts a stale state. A watchtower can do that job if your own node is offline. It does not need your spending key."},{"q":"LN-Symmetry, formerly Eltoo, is not universal yet because?","options":["It already removed all channel closes","It needs a sighash upgrade that is not activated","It is a hard fork that raised the supply","It bans mobile wallets"],"answer":1,"explanation":"Eltoo would update a channel without the penalty game. It depends on a soft-fork feature such as ANYPREVOUT that users have not activated. Today's network still uses the penalty design."},{"q":"Silent payments are specified as which BIP?","options":["BIP32","BIP141","BIP352","BIP9"],"answer":2,"explanation":"BIP352 lets a sender derive a one-time on-chain output from a receiver's static address, without a notification transaction. The receiver scans for it."},{"q":"Who are the authors associated with the BIP352 silent-payment design?","options":["A mining-pool committee","The IMF research desk","Craig Wright's court filing","Josie Baker and Ruben Somsen"],"answer":3,"explanation":"Baker and Somsen wrote the silent-payments proposal that became BIP352. It is a wallet protocol on Bitcoin, not a new coin."},{"q":"PayJoin, BIP78, breaks which surveillance shortcut?","options":["The guess that all inputs belong to one spender","The 21 million cap","The block-time target","The need for signatures"],"answer":0,"explanation":"In a PayJoin the receiver adds an input too, so \"all inputs are the sender\" is a bad guess. It is cooperative and still a normal Bitcoin transaction."},{"q":"BIP47 PayNyms give a receiver what?","options":["A miner's coinbase identity","A reusable payment code that derives fresh addresses","A dollar balance at the Fed","An automatic tax filing"],"answer":1,"explanation":"Justus Ranvier's BIP47 payment codes let two people derive addresses without reusing one on-chain address. They are different from silent payments."},{"q":"Output script descriptors, the BIP380 family, are used for what?","options":["Replacing seed phrases with email","Increasing the block weight","Writing down exactly which scripts a wallet will watch","Hiding coins from the owner"],"answer":2,"explanation":"A descriptor records the script type and derivation. Backups that store only words can miss the script type if the wallet used a non-default path."},{"q":"Miniscript is a structured way to write Bitcoin Script. Simplicity is a different language by whom?","options":["The SEC, in 2024","Andrew Poelstra alone, in 2008","Satoshi, in the genesis block","Russell O'Connor"],"answer":3,"explanation":"Miniscript was developed by Pieter Wuille, Andrew Poelstra, and collaborators. Simplicity is Russell O'Connor's 2017 language, aimed at formal proofs. Neither is required to send ordinary bitcoin."},{"q":"OP_CAT is in what state on Bitcoin mainnet?","options":["Disabled since the early years; a proposal would restore it","Required for every payment","The opcode that sets the supply","Activated in Taproot as a hard fork"],"answer":0,"explanation":"OP_CAT, which concatenates stack items, was disabled early because of denial-of-service worries. BIP347 proposes enabling it again. Until miners and nodes activate a soft fork, it is not consensus."},{"q":"The standard way to make a provably unspendable output is what?","options":["A made-up bare multisig with a story attached","An OP_RETURN output","Sending coins to a miner in a side letter","Deleting the block file"],"answer":1,"explanation":"OP_RETURN fails any spend. A random address is only unspendable if nobody ever had the key, which you cannot prove. Bare multisig with junk keys is not the usual burn tool."},{"q":"Lost-coin estimates of a few million bitcoin should be stated as what?","options":["Zero, because nodes track every owner","An exact 4,000,000 figure in the code","A rough range, not a measured census","A number the IMF certifies yearly"],"answer":2,"explanation":"Analysts guess from coins that have not moved, often a band around 2 to 4 million. Dormant is not the same as lost. Nobody can audit private keys."},{"q":"Gregory Maxwell described CoinJoin in which year?","options":["2024, after Whirlpool closed","1997","2008, in the whitepaper","2013"],"answer":3,"explanation":"Maxwell's 2013 BitcoinTalk post described users jointly building one transaction. Whirlpool and the zkSNACKs Wasabi coordinator were later services, and both of those coordinators closed in 2024."},{"q":"JoinMarket differs from a hosted mixer because?","options":["Peers coordinate CoinJoins without a custodian holding coins","It prints substitute coins","It is an ETF market maker","It requires a bank charter"],"answer":0,"explanation":"JoinMarket matches makers and takers so a CoinJoin can be built. You still sign your own inputs. It is not a promise of perfect anonymity."},{"q":"A Chaumian mint such as Fedimint or Cashu blinds tokens so that?","options":["The bitcoin supply increases","The mint cannot link the deposit to the withdrawal easily","Miners skip proof of work","The user has no exit"],"answer":1,"explanation":"Blind signatures, Chaum's 1982 idea, let a mint sign a note without seeing its serial at issuance. You still trust the mint to redeem, unless an extra federation or exit rule limits that."},{"q":"Ark, proposed by Burak Keceli, lets people hold what off a shared pool?","options":["Miner shares","A second bitcoin with its own cap","Virtual UTXOs they can exit on chain","ETF units"],"answer":2,"explanation":"An Ark service provider coordinates a pool of on-chain UTXOs. Users hold virtual outputs and keep a way to exit. The operator can stop coordinating, so the exit path matters."},{"q":"Stratum V2's job negotiation matters because?","options":["It sets a global fee","It changes SHA-256 to Scrypt","It removes pools entirely by law","The hasher, not only the pool, can pick transactions"],"answer":3,"explanation":"Stratum v1 pools usually hand miners an empty header. V2 can let the miner propose the block template, which cuts a pool's power to censor. It also encrypts the link and uses less bandwidth."},{"q":"Marek Palatinus, known as slush, is associated with which mining protocol?","options":["The original Stratum pool protocol","Taproot activation","The ETF order","BIP39's wordlist alone"],"answer":0,"explanation":"Slush started an early mining pool and the Stratum protocol that pools then standardized. Stratum V2 is the later replacement, developed in the open."},{"q":"Miner extractable value on Bitcoin is limited, compared with Ethereum, mainly because?","options":["Bitcoin has no fees at all","Bitcoin Script has no general DEX for ordering games","Miners cannot choose transactions","The whitepaper bans all ordering"],"answer":1,"explanation":"MEV is profit from choosing which transactions go in a block and in what order, beyond the public fee. Bitcoin's limited script means there is no large on-chain exchange to reorder. Fee sniping and out-of-band deals still exist."},{"q":"A discrete log contract uses an oracle to do what?","options":["Mint a new stablecoin","Hold the pot until a judge emails both sides","Sign an outcome, without taking custody of the funds","Replace the block reward"],"answer":2,"explanation":"Tadge Dryja's DLC design has an oracle attest to a number. Adaptor signatures let the right party claim the coins. You trust the oracle's honesty, not its custody."},{"q":"Tadge Dryja is known for which two bitcoin ideas?","options":["OP_CAT and the block-size hard fork","The 21 million cap and the genesis block","The spot ETF and the reserve order","The Lightning whitepaper and discreet log contracts"],"answer":3,"explanation":"With Joseph Poon he wrote the Lightning paper, drafted in 2015 with the final version in January 2016. He also described discreet log contracts, which use an oracle's signature to settle a bitcoin contract."},{"q":"BitVM, described by Robin Linus in 2023, checks heavy computation how?","options":["Off chain, with an on-chain fraud proof if someone cheats","By running an EVM inside every node","By raising the block weight to 100 MB","By trusting a company server"],"answer":0,"explanation":"The October 2023 BitVM paper uses NAND gates and challenge-response proofs. Honest runs stay off chain. It is not \"Ethereum inside Bitcoin.\""},{"q":"Taproot Assets, shipped by Lightning Labs, used to be called what?","options":["Ordinals","Taro","Liquid","Simplicity"],"answer":1,"explanation":"The project was introduced as Taro and renamed Taproot Assets. It puts asset commitments in Taproot trees and can move them on Lightning. The asset is not bitcoin."},{"q":"Fedimint is best described as what?","options":["A spot ETF","A new proof-of-work coin","A community Chaumian mint with a federation of guardians","A miner-only sidechain"],"answer":2,"explanation":"Guardians jointly custody bitcoin and issue blinded ecash notes. Users gain privacy from the federation's view of spends, and they take federation risk in return."},{"q":"Cashu is which kind of protocol?","options":["A national CBDC","A replacement for SHA-256","A hardware wallet","A simple Chaumian ecash system for bitcoin and Lightning"],"answer":3,"explanation":"Calle published Cashu so a mint can issue blind ecash notes redeemable for bitcoin or Lightning. The mint can refuse a redemption if it is malicious or broke. Notes are not on-chain bitcoin until you exit."},{"q":"BIP 141 records the witness commitment in which transaction?","options":["The block's coinbase transaction","The last transaction in the block","A separate extension block","The previous block's header"],"answer":0,"explanation":"BIP 141 commits the witness merkle root through the coinbase transaction, in a scriptPubKey of that coinbase, so the change could be a soft fork. Source: https://github.com/bitcoin/bips/blob/master/bip-0141.mediawiki"},{"q":"546 sats is the dust limit for which output, under which default fee?","options":["Any output at 1 sat per byte","A legacy P2PKH output at 3 sat/vB dust relay fee","A Lightning channel of any size","A consensus ban below 1,000 sats"],"answer":1,"explanation":"Bitcoin Core's default dust relay fee is 3 sat/vbyte. Counting a P2PKH output plus the bytes needed to spend it yields 546 sats. Other script types have other limits. It is policy."},{"q":"The six-day gap from the genesis block to block 1 proves what?","options":["That difficulty was already at the 2024 target","That Satoshi's CPU mined for exactly six days","Nothing precise about how long the hash search took","That the whitepaper was published in 2010"],"answer":2,"explanation":"Block 0 is timestamped January 3, 2009 and block 1 January 9. People theorize about the gap. Timestamps alone do not measure the search."},{"q":"HODL entered bitcoin slang from which event?","options":["A line in the whitepaper","A ticker symbol chosen by Satoshi","An ETF prospectus in 2024","A December 18, 2013 BitcoinTalk typo by GameKyuubi"],"answer":3,"explanation":"GameKyuubi's drunk post \"I AM HODLING\" stuck. It means holding through volatility. It is not a strategy guarantee or financial advice."},{"q":"Laser eyes on a profile picture, from 2021, signaled what?","options":["A cultural bet on bitcoin, not a protocol role","That the account is a Core maintainer","A completed KYC check","Membership in a mining pool"],"answer":0,"explanation":"The laser-eye meme marked public enthusiasm during the run toward a $100,000 quote. It conferred no keys, no job, and no vote on consensus."},{"q":"The honey badger meme says bitcoin is hard to stop. It is what?","options":["A mining-pool name in the genesis block","A joke about toughness, not an animal in the code","A BIP that bans forks","A satellite callsign"],"answer":1,"explanation":"People reused the honey-badger clip to talk about censorship resistance. Nothing in the consensus rules mentions the animal."},{"q":"Unicode added the bitcoin sign in which release?","options":["ASCII in 1963","The 2008 whitepaper font","Unicode 10.0, in June 2017","The genesis block"],"answer":2,"explanation":"U+20BF, ₿, arrived in Unicode 10.0 in June 2017. The ticker BTC is older and is a convention, not a consensus field."},{"q":"\"Stacking sats\" means what in ordinary usage?","options":["Merging every UTXO every day","Building a stack of ASIC heaters only","Running a satellite dish","Buying small amounts over time"],"answer":3,"explanation":"A sat is one hundred-millionth of a bitcoin. Stacking means accumulating them, often on a schedule. The phrase is not advice to buy."},{"q":"A pleb, in bitcoin slang, is who?","options":["An ordinary person saving in bitcoin, said with affection","A licensed broker","A Core release signer only","A central banker"],"answer":0,"explanation":"The word was borrowed as a badge for regular users, as opposed to institutions. It does not change the rules your node enforces."},{"q":"\"Few understand\" and \"tick tock, next block\" are what?","options":["Error strings in Bitcoin Core","Community catchphrases","Articles of the IMF","Mining-pool payout codes"],"answer":1,"explanation":"They are memes. The next block still arrives only when someone finds a valid hash. The phrases do not predict a price."},{"q":"Which statement is a slogan, not a medical or price fact?","options":["Nodes reject invalid blocks","There will never be more than 21 million","Fix the money, fix the world","SHA-256 is the mining hash"],"answer":2,"explanation":"The slogan is a political hope that sounder money improves society. It is not a clinical claim and not a forecast of next year's price."},{"q":"Low time preference, as economists use it, means what?","options":["A block every ten seconds","A diet plan certified by Bitcoin Core","A guarantee of investment returns","Valuing a future good enough to wait or save"],"answer":3,"explanation":"Time preference is how much you discount the future. Bitcoiners also use the phrase for habits that pay later. That analogy is not medical advice."},{"q":"Self-reliance in a bitcoin context most concretely means what?","options":["Holding your own keys and checking your own node","Outsourcing both keys and verification","Trusting a headline for your balance","Sending your seed to a custodian"],"answer":0,"explanation":"The protocol will not recover a lost seed and will not stop a custodian from failing. Running a node and holding keys are the practical version of \"don't trust, verify.\""},{"q":"Which claim is an opinion, not a rule of the chain?","options":["Supply is capped near 21 million","A particular diet is required of bitcoiners","Proof of work orders the blocks","Signatures authorize spends"],"answer":1,"explanation":"Health and food choices show up in the community because people connect them with long-term thinking. They are not consensus rules, and this archive does not give medical advice."},{"q":"The Fiat Standard is which kind of book?","options":["An SEC rulebook","The Bitcoin Core user manual","Saifedean Ammous's argument about debt-based money","A mining-pool contract"],"answer":2,"explanation":"Ammous followed The Bitcoin Standard with The Fiat Standard, an argument about fiat credit, including how he thinks it shapes food and time preference. The chain does not depend on the book."},{"q":"Honest scales, as in Proverbs 11:1, are cited by some readers as what?","options":["A requirement to join a church","A hidden message in the genesis block","A BIP that sets the subsidy","A moral parallel to money that is hard to debase"],"answer":3,"explanation":"The proverb condemns a false balance. Some people of faith use it as a parable for sound money. Bitcoin itself has no religious test."},{"q":"War finance and hard money are linked in the historical argument how?","options":["Printing money has often paid for wars, so harder money raises that cost","Bitcoin Core forbids armies","The whitepaper sets a defense budget","Halvings fund a national military"],"answer":0,"explanation":"Governments have debased currency to fund conflict. Bitcoiners argue a money that is hard to expand makes that path more expensive. It is not a promise of peace."},{"q":"A bitcoin ETF share is safer than self-custody in which narrow sense, and worse in which?","options":["The share is a UTXO in your wallet","The broker holds the paperwork; you do not hold the key","The fund cannot be hacked","The share is legal tender worldwide"],"answer":1,"explanation":"An ETF can fit a retirement account and removes the user's key-management job. The user has an IOU from a fund structure, not a coin they can spend on chain. That tradeoff is the point, not a recommendation."},{"q":"Public company bitcoin treasuries should be quoted how?","options":["As the same number as the genesis reward","As a constant written in the protocol","As a dated figure, because they keep buying or selling","As a US legal-tender reserve"],"answer":2,"explanation":"Treasury announcements change. A quiz that memorizes one coin total will go stale. The protocol total, near 21 million, does not."},{"q":"What is a PSBT?","options":["A pruned block file","A new address format that hides the amount","A pool payout share","A partially signed transaction you can pass to another signer"],"answer":3,"explanation":"BIP174 lets wallets exchange a transaction that is not fully signed. Hardware wallets and multisig coordinators use it so the online machine never needs every key."},{"q":"SeedSigner is which design?","options":["A do-it-yourself air-gapped signer on a camera and Pi","A custodial mobile exchange","A mining ASIC","A bank HSM you cannot build"],"answer":0,"explanation":"SeedSigner loads a seed from dice or a scan, signs, and is meant to forget the key when powered off. It is open hardware. It is not a Coldcard, and it does not need a manufacturer account."},{"q":"The Trezor One shipped in 2014 with which security choice?","options":["A hidden chip nobody could audit","No secure element, so the design stayed reviewable","A built-in LTE radio","A custodian key escrow"],"answer":1,"explanation":"SatoshiLabs' Trezor One avoided a closed secure element. Later Trezor models and Coldcard made different chip choices. The debate is open design versus tamper resistance."},{"q":"Sparrow Wallet is useful for which job?","options":["A social network","A proof-of-work replacement","A desktop wallet with coin control and PSBT multisig","An ETF broker"],"answer":2,"explanation":"Sparrow is a Bitcoin-only desktop wallet. It can talk to your node, label UTXOs, and coordinate multisig. It is software, so the machine you run it on still matters."},{"q":"Electrum, started by Thomas Voegtlin, is known as what?","options":["El Salvador's Chivo app","The first ASIC manufacturer","A 2024 ETF","A long-lived lightweight wallet, from 2011"],"answer":3,"explanation":"Electrum began in 2011 and still lets you connect to your own server or Electrum servers. Lightweight verification is not the same as checking every rule yourself."},{"q":"Phoenix wallet's approach to Lightning is what?","options":["A mobile app that manages channels for you, non-custodial","A custodian that holds the seed","A miner of empty blocks","An on-chain-only watch wallet"],"answer":0,"explanation":"ACINQ's Phoenix opens and resizes channels so the phone user does not splice by hand. You still have keys in the app. That is different from a custodial wallet such as Wallet of Satoshi."},{"q":"Wallet of Satoshi is taught as what kind of Lightning wallet?","options":["A cold-storage multisig","A custodial wallet: they hold the keys","An implementation of Bitcoin Core","A hardware signer"],"answer":1,"explanation":"It is easy because the company custodies the balance. If the company stops, the balance is their liability, not a UTXO you can sweep. Convenience has a counterparty."},{"q":"Umbrel, Start9, and RaspiBlitz are examples of what?","options":["Mining-pool payout schemes","Spot bitcoin ETFs","Operating-system images that make a node easier to run","Hardware wallets"],"answer":2,"explanation":"They package Bitcoin Core and extra apps on a small computer. You still need disk and bandwidth. A pruned node lowers the disk need. The chain itself is hundreds of gigabytes and growing if you keep every block."},{"q":"Initial block download is heavy because the node must what?","options":["Buy an ETF share","Ask one website for a balance","Mine from genesis","Download and check history before it trusts its wallet"],"answer":3,"explanation":"A new full node verifies from the genesis block forward. Assumevalid can skip some old signature checks for speed, and you can turn that off. Pruning does not skip the check; it only deletes files later."},{"q":"A light wallet that trusts a server can be lied to about what?","options":["A payment the server pretends is confirmed","The SHA-256 algorithm","The user's own seed, which the server must store","The 10-minute target"],"answer":0,"explanation":"SPV and Electrum-style clients ask someone else for proofs or for status. Compact block filters (BIP157/158) avoid telling that server your addresses the way BIP37 bloom filters did."},{"q":"BIP37 bloom filters were replaced in careful wallets because they did what?","options":["They made blocks 4 MB of consensus weight","They leaked which addresses the wallet cared about","They removed fees","They published the seed"],"answer":1,"explanation":"A bloom filter sent to a peer narrows the transactions you want, and it can be attacked or logged. BIP157 compact filters let you download a filter and match it locally."},{"q":"Neutrino is a wallet mode that uses what?","options":["A custodian's database only","The old bloom-filter leak","Compact block filters, BIP157 and BIP158","A miner bribe"],"answer":2,"explanation":"Neutrino-style clients fetch filters and scan them privately. They still do not check every consensus rule the way your own full node does."},{"q":"Replacing a confirmed payment requires what?","options":["A passphrase change","A support email to Bitcoin Core","An ETF redemption","A reorg deeper than the confirmation, which gets expensive fast"],"answer":3,"explanation":"Each confirmation is more proof of work on top. There is no chargeback desk. Six confirmations is a custom for large payments, not a magic consensus constant."},{"q":"A 51 percent attack means a majority of what?","options":["Recent hash rate, not a majority of human voters","Exchange accounts","Node operators by count only","ETF shares"],"answer":0,"explanation":"If an attacker can outwork the honest hash rate, they can try to rewrite recent blocks. They still cannot spend coins without signatures, and they cannot change the rules your node accepts."},{"q":"Selfish mining, in the Eyal and Sirer paper, is what claim?","options":["Every pool is already doing it successfully","Withholding blocks can pay a miner under the paper's assumptions","It is impossible above 1 percent hash rate","It changes the supply cap"],"answer":1,"explanation":"The 2013 paper argued that a miner who hides blocks might earn more than their hash share in some conditions. It is an attack on fairness assumptions, not a routine feature."},{"q":"Empty blocks still happen sometimes because?","options":["Nodes require one transaction","The protocol pays a bonus for emptiness","A miner may start hashing a template before transactions arrive","Fees are illegal"],"answer":2,"explanation":"The coinbase is enough for a valid block. Pools that send a header before the transactions can win an empty block. Stratum V2 and better template timing aim to reduce that."},{"q":"Hashprice is what unit?","options":["A hardware-wallet model","The price of one bitcoin","The difficulty integer","Expected revenue per unit of hashrate per day"],"answer":3,"explanation":"Miners talk about dollars or sats per terahash per day. It moves with price, fees, and difficulty. It is not a protocol field."},{"q":"After a halving, less efficient miners often do what?","options":["Turn off until price or fees cover their power","Receive a bonus subsidy","Get a vote to undo the halving","Switch the hash to SHA-1"],"answer":0,"explanation":"The subsidy drop is instant and the difficulty does not drop with it. High-cost machines stop. Difficulty later adjusts if hashrate actually falls."},{"q":"The security-budget debate is about which open question?","options":["Whether SHA-256 has already been broken","Whether fees will pay miners after the subsidy is tiny","Whether nodes will delete the chain in 2030","Whether the ETF replaced mining"],"answer":1,"explanation":"As the subsidy falls, fees are a larger share of miner pay. Whether that will be enough in the far future is debated. It is not settled, and it is not a reason to invent a tail emission in the rules."},{"q":"Monero's tail emission is often cited as what contrast?","options":["The same schedule as the 21 million cap","A bitcoin soft fork that already passed","0.6 XMR per block forever, which Bitcoin's rules do not have","A Lightning feature"],"answer":2,"explanation":"Monero kept a small perpetual subsidy. Bitcoin's consensus subsidy goes to zero. People argue about whether that was wise. Changing it would be a hard fork almost everyone would have to accept."},{"q":"A hard fork that raises the supply would succeed only if?","options":["Satoshi's old key signed a blog post","One pool mined a single block","An ETF issuer filed a form","The economic majority ran the new rules, which they need not do"],"answer":3,"explanation":"Nodes that keep the old rules reject the extra coins. A minority chain can exist, as other forks have, without becoming bitcoin as the users define it."},{"q":"Soft forks tighten rules. Nodes that have not upgraded usually do what?","options":["Still accept the blocks, if the new rules are a subset","Reject every block forever","Start a new supply schedule","Lose their wallet"],"answer":0,"explanation":"If the fork only makes valid blocks a smaller set, old nodes see the blocks as valid. They do not enforce the new rule themselves. That is why upgrades still need wide node adoption to matter."},{"q":"The 2017 New York Agreement and BIP148 were about what fight?","options":["The color of the logo","How to activate SegWit, and whether to raise the base block size","The pizza price","The 2024 ETF fee"],"answer":1,"explanation":"Some companies wanted a block-size increase bundled with SegWit. BIP148 was a user-activated client that would reject non-signaling blocks after August 1, 2017. SegWit activated; Bitcoin Cash forked instead."},{"q":"Bitcoin Cash forked on which date, and what did it change?","options":["January 3, 2009, the genesis block","November 14, 2021, adding Taproot","August 1, 2017, raising its block-size limit","April 2024, the halving"],"answer":2,"explanation":"BCH split off with a larger block-size rule. The chain people still call Bitcoin kept the SegWit path and the smaller base block. A fork does not move your coins unless you sign a transaction on that fork."},{"q":"Replay protection matters after a fork because?","options":["ETFs rebalance automatically","Miners copy your seed","The halving happens twice","A transaction you sign might otherwise be valid on both chains"],"answer":3,"explanation":"If both chains accept the same signature, spending on one can spend on the other. A careful fork changes the sighash. Users should still use wallets that understand the split."},{"q":"Ordinal theory, published by Casey Rodarmor in January 2023, tracks what?","options":["Individual sats through transactions, as a social convention","A consensus change to the supply","A new opcode that Core v30 forbade","A Lightning channel type"],"answer":0,"explanation":"Ordinal numbers are a way to count sats. Inscriptions then store data in a Taproot witness. Nodes that did not upgrade still accept the transactions. The debate is about block space, not a new coin cap."},{"q":"Inscriptions are controversial mainly because?","options":["They change miner signatures into blank checks","They bid for block space that payments also use","They raise the 21 million cap","They shut down pruned nodes"],"answer":1,"explanation":"A large witness still pays a fee, and the weight limit still holds. Critics call non-monetary data spam. Defenders say paying the fee is the filter. Core's 2025 relay-policy change heated that argument again."},{"q":"Bitcoin Knots versus Bitcoin Core in the OP_RETURN fight was about what?","options":["Which ETF to buy","Who owns the genesis key","Default relay policy, not the consensus supply","A hard fork to 8 MB blocks"],"answer":2,"explanation":"Core v30 relaxed the default size of OP_RETURN data it will relay. Knots kept a tighter default. A block that is consensus-valid can still be relayed by miners who build it themselves."},{"q":"Replace-by-fee and the mempool interact how?","options":["The node calls the sender","The older one is frozen after one second","Both must be mined","A higher-fee double spend can evict the older unconfirmed one"],"answer":3,"explanation":"Until a transaction is in a block, a replacement that pays more can win under the node's policy. Merchants who deliver goods on zero confirmations accept that risk."},{"q":"Package relay matters for which stuck-transaction case?","options":["A low-fee parent with a high-fee child that nodes should consider together","A confirmed coinbase","An ETF creation basket","A seed backup"],"answer":0,"explanation":"If nodes look at the parent alone, they may ignore a child that would pay them well. Package acceptance is the work of considering the pair. It does not change consensus validity."},{"q":"Vbytes are related to weight how?","options":["Vbytes replace signatures","Virtual size is weight divided by four","Vbytes are only a Lightning unit","One vbyte is one satoshi"],"answer":1,"explanation":"4,000,000 weight units equal 1,000,000 vbytes. Fee rates in sat/vB are satoshis per virtual byte. Witness bytes are cheaper in this accounting, which was the SegWit discount."},{"q":"A transaction's weight counts witness bytes as what?","options":["Zero, so witnesses are free","The same as legacy bytes","1 weight unit per byte, versus 4 for non-witness bytes","100 weight units per byte"],"answer":2,"explanation":"That discount is why SegWit and Taproot spends are cheaper per byte of signature data than old P2PKH spends. The block still has a hard weight cap."},{"q":"Coin control lets a spender do what?","options":["Change a confirmed output","Set the dollar price","Force a miner to take the fee","Choose which UTXOs to include, instead of letting the wallet mix them blindly"],"answer":3,"explanation":"Picking inputs avoids merging unrelated coins in one transaction. It also lets you leave dusty or poisoned outputs alone. Labels help only if you recorded them."},{"q":"A change output is what?","options":["The part of the inputs that comes back to your wallet","A fee paid to the relay","A Lightning penalty","An ETF dividend"],"answer":0,"explanation":"Bitcoin does not debit an account. It spends whole UTXOs and creates new ones. Whatever you do not pay out or leave as a fee should come back to an address you control."},{"q":"Why do wallets avoid sending change to the same address you paid from?","options":["The protocol rejects change","It links the payment to the rest of that address's history","Miners burn change","Change is always 546 sats"],"answer":1,"explanation":"A fresh change address is ordinary privacy practice. Reusing the spend address tells an observer that the leftover is yours and ties future payments together."},{"q":"The BIP44 gap limit of 20 means what?","options":["Channels close after 20 days","You may only own 20 UTXOs","A wallet stops looking after 20 unused addresses in a row","Seeds have 20 words"],"answer":2,"explanation":"When restoring, the wallet scans the chain of addresses until it sees a long unused gap. If you received on an address past that gap and nothing filled the hole, a restore can miss it. Some wallets let you raise the limit."},{"q":"An xpub can do what, and what can it not do?","options":["Reset a passphrase","Spend every coin","Sign a peer's Lightning channel","Show addresses and balances, but not spend"],"answer":3,"explanation":"An extended public key derives the public side of a branch. Anyone with it can watch those addresses. It is not a spend key. Still, publishing it hurts privacy."},{"q":"An xprv should be treated as what?","options":["A master secret for that branch, as sensitive as a seed","A public account number","A watch-only string safe to email","A pool username"],"answer":0,"explanation":"An extended private key derives child private keys. Leak it and those coins are spendable. Back it up like a seed, or don't export it at all."},{"q":"WIF, wallet import format, is what?","options":["A 24-word phrase","A Base58 encoding of a single private key","A block header","A Lightning invoice"],"answer":1,"explanation":"Older wallets exported one key in WIF. A single key is not a BIP32 tree. Importing it does not restore later addresses unless you import those keys too."},{"q":"Base58Check drops which characters, and why?","options":["The digit 1, which is reserved for miners","Every vowel, as a privacy feature","0, O, I, and l, because they look alike","Unicode letters, because of the ₿ sign"],"answer":2,"explanation":"The encoding avoids ambiguous glyphs so a key or address can be read aloud or typed with fewer mistakes. A checksum catches most typos."},{"q":"Bech32's checksum is stronger than Base58Check at catching what?","options":["A wrong passphrase","A stolen seed","A reorg of six blocks","Typos, including some that Base58 could miss"],"answer":3,"explanation":"Bech32 was designed so common typing errors fail the checksum. It does not tell you the coins are yours if you send them to a real but wrong address that still checksums."},{"q":"A passphrase written in the wrong case does what?","options":["Opens a different wallet, usually empty","Corrects itself","Triggers a Core warning email","Halves the coins"],"answer":0,"explanation":"The passphrase is a free string, case-sensitive. \"Secret\" and \"secret\" are two wallets. There is no recovery hint on chain."},{"q":"Diceware-style entropy for a 24-word seed needs about how many bits?","options":["12 coin flips","256 bits of randomness","The current bitcoin price","A birthday"],"answer":1,"explanation":"Twenty-four words carry 256 bits. Coin flips, dice, or a hardware TRNG can supply them. A brain wallet made from a song lyric is not in this class: attackers guess phrases."},{"q":"A brainwallet from a famous quote is weak because?","options":["BIP39 forbids letters","SHA-256 cannot hash words","Other people can guess the phrase and scan for the coins","Nodes reject low entropy"],"answer":2,"explanation":"If the phrase is in a song or a book, a scanner can try it. BIP39 words from a good RNG are not that kind of wallet. Do not invent a seed from a motto."},{"q":"Metal backups are preferred to paper for which mundane reason?","options":["Steel changes the derivation path","Metal is required by consensus","Paper cannot hold 24 words","Fire and flood destroy paper more easily"],"answer":3,"explanation":"A seed is information. Steel or titanium survives a house fire better than notebook paper. The metal does not make the words secret if you leave it in a photo."},{"q":"A decoy wallet using a passphrase is sometimes called what?","options":["Plausible deniability, if the decoy has a little money","A miner honeypot","An ETF sleeve","A pruned node"],"answer":0,"explanation":"Under coercion you might reveal a passphrase that opens a small wallet. The rest sits under another passphrase. This only helps if you planned it, and it can make inheritance harder."},{"q":"Multisig is not the same as Shamir splitting because?","options":["They are two names for BIP39","Multisig needs several keys to sign; Shamir splits one secret","Shamir creates extra bitcoin","Multisig removes fees"],"answer":1,"explanation":"In k-of-n multisig, different people or devices hold keys, and a transaction needs k signatures. SLIP39 Shamir splits one seed so k shares reconstruct it. Reconstructing a seed puts the whole key in one place at that moment."},{"q":"A 2-of-3 inheritance setup can include whom?","options":["A miner, a node, and an ETF","Only the exchange compliance desk","You, a heir, and a recovery key in another place","Three copies of the same seed in one drawer"],"answer":2,"explanation":"You spend with two keys day to day, or you and a heir, depending on the policy. Three copies of one seed in one house are not multisig. Write the policy down without writing the seeds in the same letter."},{"q":"Spending bitcoin for goods in the United States can create what tax event?","options":["A miner fee only","No record, because bitcoin is currency in that notice","An automatic exemption for all amounts","A disposal of property, under Notice 2014-21"],"answer":3,"explanation":"The IRS treats it as property, so spending can realize gain or loss against your basis. Rules change and other countries differ. Keep records. This is not tax advice."},{"q":"A custodian bankruptcy usually leaves customers as what?","options":["Unsecured creditors, unless a specific law says otherwise","Full nodes","Holders of the UTXO by default","Miners of the remaining coins"],"answer":0,"explanation":"FTX in 2022 showed a balance on a website is not a key. Some jurisdictions later passed rules to segregate customer coins. You have to read the actual entity. \"Not your keys\" is the conservative reading."},{"q":"Proof of reserves, if done with a real signature over the liability list, shows what?","options":["That the coins cannot be lent","That some keys signed, not that the company is solvent tomorrow","That your withdrawal will clear","That the seed is in a glacier"],"answer":1,"explanation":"A signature proves control of UTXOs at a moment. It does not prove those coins are owed to you, or that liabilities are complete, or that the coins stay put. It is a tool, not a substitute for self-custody."},{"q":"Dollar-cost averaging means what, and what does it not mean?","options":["A tax-free status","A protocol discount every Thursday","Buying a fixed amount on a schedule; it does not remove risk","A miner subsidy"],"answer":2,"explanation":"DCA spreads purchases over time so you do not pick one day. You can still lose money. It is a habit, not a promise, and not advice to buy."},{"q":"A cold wallet and a hot wallet are split so that?","options":["The hot wallet is always a hardware device","The hot wallet earns interest from miners","The cold wallet has no keys","Daily spending money is separate from long-term savings"],"answer":3,"explanation":"The hot side can be a phone with a small balance. The cold side stays offline. Refilling the hot wallet is an on-chain or Lightning transfer you plan, not an emergency seed import on a browser."},{"q":"Verifying a receive address on the device screen stops which failure?","options":["Malware that swaps the address on the computer display","A reorg","A halving","A fee spike"],"answer":0,"explanation":"The computer can lie. The hardware wallet shows the address it will pay or the address it derived. Read it, including the middle characters, not just the first and last four."},{"q":"A watch-only wallet is good for what?","options":["Signing a high-value payment on a phone","Monitoring a cold wallet's balance without the spend key","Publishing an xprv","Mining"],"answer":1,"explanation":"Import the xpub or descriptor, not the seed. You can see incoming coins and build a PSBT somewhere safer. The watch wallet cannot spend if you set it up correctly."},{"q":"Labeling UTXOs matters later because?","options":["Labels are required for validity","Miners keep a contact book","The chain does not store your notes about who paid you","Change outputs are illegal"],"answer":2,"explanation":"Once coins merge, the histories merge for an observer. Labels live in your wallet file. Back them up with the wallet, not only the seed, or the names are gone even though the coins remain."},{"q":"Consolidation of many small UTXOs is cheapest when?","options":["After you publish your xpub","Fees are at their peak","During a reorg","Fees are low, so the future spend is smaller"],"answer":3,"explanation":"Each input costs bytes later. Combining them when block space is cheap can save sats. Do it with eyes open: one consolidation links those coins together."},{"q":"A CPFP bump of your own receive works only if?","options":["You have the key to spend that unconfirmed output","The sender revealed their seed","The payment is already confirmed","The ETF market is open"],"answer":0,"explanation":"If someone paid you and the fee is too low, you can spend that output with a higher fee so miners want both transactions. If you cannot spend it yet, you need the sender to RBF or to cooperate."},{"q":"Anchored Lightning channels and fee bumping exist because?","options":["Lightning forbids on-chain fees","Commitment transactions sometimes need a way to get confirmed","The block reward pays channel closes","Watchtowers mine the blocks"],"answer":1,"explanation":"If a channel force-closes and the fee environment changed, the commitment must still confirm. Anchor outputs let a party add fees later. Details depend on the Lightning version."},{"q":"Sphinx-style onion routing on Lightning hides what from an intermediate node?","options":["Your seed phrase","The amount of every hop in cleartext to the world","The full route, so a hop sees only the previous and next hop","The on-chain channel UTXO"],"answer":2,"explanation":"Each hop peels one layer, like Tor. It learns where to forward and the fee it may take, not the whole path. Channel balances and timing can still leak information."},{"q":"A Lightning invoice includes what you should check before paying?","options":["The ETF ticker","The sender's seed","A miner's signature","The amount, the expiry, and the description or recipient"],"answer":3,"explanation":"Invoices expire, and a swapped invoice pays someone else. BOLT 11 invoices are long; wallets show a payee name only if you have a contact. When in doubt, match out of band."},{"q":"Opening a Lightning channel is an on-chain transaction because?","options":["The capacity has to be locked in a real UTXO","Lightning has its own genesis block","Nodes gift free capacity","The mempool is skipped"],"answer":0,"explanation":"Until the funding transaction confirms, there is no channel. After that, payments can move off chain. Closing settles back to the chain. Splicing, where supported, resizes without a full close."},{"q":"Splicing, where two implementations support it, does what?","options":["Creates a new bitcoin","Changes channel capacity without closing and reopening from scratch","Removes the need for signatures","Converts an ETF to a channel"],"answer":1,"explanation":"Splice-in or splice-out spends the old funding output into a new one. It is still on chain once. Support has to exist on both sides, so it is not universal yet."},{"q":"Zap, in nostr slang, is what?","options":["A BIP39 word","A mining share","A Lightning tip attached to a signed note","A hard-fork vote"],"answer":2,"explanation":"Nostr notes are signed events on relays. NIP-57 describes zaps: a Lightning payment that references the note. The relay is not a bank, and the Lightning part still follows Lightning's rules."},{"q":"Your nostr identity is what?","options":["A miner coinbase tag","A username a company can reset","Your Exchange KYC file","A key pair; the secret key is as sensitive as a bitcoin seed"],"answer":3,"explanation":"npub is the public key. nsec is the secret. Relays can refuse to store a note, but they cannot forge one without the key. Do not paste an nsec into a website."},{"q":"Jack Dorsey funded nostr development in 2022 with what?","options":["About 14 BTC donated to developers","The genesis coins","A seat on the Federal Reserve","The Bitcoin Core release keys"],"answer":0,"explanation":"The gift was a donation to developers, not a purchase of the protocol. Nostr has no company that owns the key format. Clients and relays still come and go."},{"q":"Which nostr client choice is a preference, not a protocol rule?","options":["A single official client shipped in Bitcoin Core","Amethyst, Primal, or another app that speaks the same protocol","A client that must custody your nsec on a server","A client that mines blocks"],"answer":1,"explanation":"The channel lists several clients. They are interchangeable only if you keep your own key. The protocol is the signed events, not the logo of the app."},{"q":"A bitcoin job board such as Bitcoiner Jobs is what?","options":["A consensus soft fork","A miner of salaries","A listing site for employers, not a source of free coins","An ETF payroll"],"answer":2,"explanation":"Companies post roles there and on boards such as 603 BTC. A listing is an ad. It does not verify the employer, and it does not change how wages should be custodied once paid."},{"q":"Earning bitcoin and keeping it are different steps because?","options":["Lightning cannot pay a salary","Wages arrive already in cold storage by protocol","Employers must pay on chain","A paycheck can land at a custodian you should move off of"],"answer":3,"explanation":"An employer might pay to an exchange account or a Lightning address. Moving savings to keys you hold is a separate choice. Tax treatment of wages is its own topic, not advice in this question."},{"q":"A referral link pays whom, and what should you still do?","options":["It pays the referrer; you still check the company yourself","It raises your on-chain balance by consensus","It is a Core-endorsed vendor","It removes fees"],"answer":0,"explanation":"Affiliate links are advertising. The archive's referral channel is a list, not a promise of yield. Never send a seed to a site you reached from a link."},{"q":"Learning resources such as learnmeabitcoin.com are best used as what?","options":["A hot wallet","Explanations you can check against your own node or the code","A price oracle","A substitute for the whitepaper's actual text"],"answer":1,"explanation":"Secondary sites, glossaries, and podcasts can be wrong or outdated. The chain and the open-source code are the references. This quiz follows those, not a guru."},{"q":"Bitcoin Audible and What Bitcoin Did are examples of what?","options":["ETF issuers","Mining pools","Podcasts that discuss bitcoin, not protocol authorities","Node implementations"],"answer":2,"explanation":"Guy Swann's Bitcoin Audible reads essays aloud. Peter McCormack hosts What Bitcoin Did. Stephan Livera, Preston Pysh, Robert Breedlove, and Natalie Brunell also host well-known shows. A podcast is not a BIP."},{"q":"Mastering Bitcoin, by Andreas Antonopoulos, is aimed at whom?","options":["Miners only","People who want a price target","Regulators writing a ban","Readers who want the technical mechanics"],"answer":3,"explanation":"The book, also posted freely by the author, walks through transactions, scripts, and keys. The Internet of Money, from his talks, is more about why. Neither book can spend your coins."},{"q":"The Bitcoin Standard, by Saifedean Ammous, argues from which tradition?","options":["Austrian-style monetary history and hard money","Modern Monetary Theory as its hero","A case for altcoin premines","A manual for ASICs"],"answer":0,"explanation":"The book compares historical money with bitcoin's supply. You can disagree with it. It does not change consensus, and its food chapters are argument, not medical guidance."},{"q":"Inventing Bitcoin, by Yan Pritzker, is often recommended as what?","options":["A legal brief","A short plain-language explanation of the design","A hardware schematic","A novel about pizza"],"answer":1,"explanation":"It is a brief walk through why the pieces fit. Pair it with the whitepaper when you want the original wording."},{"q":"Banking on Bitcoin (2016) and The Rise and Rise of Bitcoin (2014) are what?","options":["ETF prospectuses","Protocol specifications","Documentaries, useful as history and not as oracles","Core release notes"],"answer":2,"explanation":"Films compress history and can simplify. Check dates and claims against the record. The channel also points at news coverage of Bitcoin Beach in El Zonte."},{"q":"El Zonte, called Bitcoin Beach, mattered because?","options":["It manufactures ASICs","It is where the genesis block was mined","It hosts the SEC","A village used bitcoin for local trade before the national law"],"answer":3,"explanation":"Grassroots payments in El Zonte preceded El Salvador's 2021 law. The national policy later changed in 2025 so shops need not accept bitcoin. A specific TV segment is not cited here."},{"q":"A song titled Satoshi Nakamoto, or any bitcoin meme song, has what protocol status?","options":["None. It is culture","It is hashed into every block","It sets the difficulty","It is a BIP"],"answer":0,"explanation":"Art, merch, and music express the culture. They do not select the chain. Spend or tip the artist if you want to; that is a normal payment."},{"q":"The orange B logo is best treated as what?","options":["A hash function","A community trademark-style mark, not a consensus object","An address prefix required by nodes","A government seal"],"answer":1,"explanation":"Nodes do not check a logo. Brands can drift, and trademark fights have happened around the mark. The chain would keep producing blocks if every icon disappeared."},{"q":"Games that pay out over Lightning, such as titles using ZBD, still require what?","options":["A miner in the console","A special game-only bitcoin","The same caution about keys and custodian risk","An ETF account"],"answer":2,"explanation":"ZBD and similar platforms settle rewards with Lightning. If the game custodies the balance, it is not cold storage. Fun is fine. Savings do not have to live in the game."},{"q":"Lightnite was an early example of what?","options":["A satellite","A consensus client","A hardware wallet","A game that tried to use Lightning for in-game value"],"answer":3,"explanation":"It was a battle-royale experiment, not a standard. Games come and go. The lesson is that Lightning can move small payments, not that a game studio is a bank."},{"q":"A curriculum that starts with \"what is money\" before \"what is a key\" is doing what?","options":["Putting the purpose ahead of the tool","Violating a BIP","Requiring a university license","Setting a price target"],"answer":0,"explanation":"Keys make no sense if you do not know what you are keeping. The archive's one-stop path is: scarce money, then custody, then a node. There is no official global syllabus."},{"q":"Charts of halvings are educational when they are used to show what?","options":["That the next candle is known","That issuance steps down on a schedule","That fees will be zero","That hashrate is a price"],"answer":1,"explanation":"A cycle chart is history. People overlay it with prices and then overfit. The only part written into the software is the subsidy schedule and the difficulty retarget."},{"q":"On-chain analysts who publish a single \"true\" price model are offering what?","options":["Financial advice from the protocol","A field in the block header","A hypothesis you can discard","A node consensus vote"],"answer":2,"explanation":"Models such as stock-to-flow or a power law fit the past until they do not. Bitcoin Core will not enforce them. Do not treat a chart as a promise."},{"q":"The word toxic, inside bitcoin arguments, usually points at what behavior?","options":["A required tone for Core merges","A chemical property of ASICs","A BIP for rude error codes","Blunt refusal to promote altcoins or obvious scams"],"answer":3,"explanation":"Some people use the word as praise for clear lines, and others as a complaint about hostility. Either way it is a social label. It does not appear in the validation code."},{"q":"An unpopular opinion is safest in a quiz when the question asks you to identify what?","options":["That it is an opinion, not a rule about blocks","That the opinion is therefore false","That the opinion will pass as a soft fork","That nodes must adopt it"],"answer":0,"explanation":"You can think the block size should have been bigger, or that fees will fail, without those views being facts. Mark the protocol facts separately from the arguments."},{"q":"A timestamped prediction is useful later because?","options":["The chain pays the predictor","You can check it against what happened","Miners must honor it","It freezes the price"],"answer":1,"explanation":"Writing a date and a claim lets other people grade you. A meme target with no date cannot be wrong. Neither kind is a consensus rule."},{"q":"Technical analysis of bitcoin charts can teach what without becoming advice?","options":["That a pattern must repeat","Which day to sell","The names of tools, such as a moving average","A guaranteed cycle"],"answer":2,"explanation":"A moving average, a range, or a volume bar is a description of past trades. Using it to trade is your own risk. This quiz will not tell you to buy or sell."},{"q":"If someone says \"bitcoin always rises every four years,\" the careful reply is?","options":["ETFs repealed the halving","The whitepaper sets the price","Difficulty forces the price up","Issuance drops about every four years; the price is not a law"],"answer":3,"explanation":"The halving is real. Demand, fees, and macro conditions are not in that formula. Past cycles are a sample of a few events. They are not a promise."},{"q":"Peaceful trade in bitcoin is voluntary in which precise sense?","options":["Nobody is forced to accept it, and nobody is forced to mine","Every shop must take it","Every citizen receives an equal UTXO","Nodes draft users"],"answer":0,"explanation":"A soft fork or a law can change a shop's choices in a given country. The protocol does not conscript miners or users. El Salvador's 2025 reform made that voluntariness explicit for merchants there."},{"q":"A government can make bitcoin harder to use locally. What can it not do with a statute alone?","options":["Regulate an exchange it licenses","Erase a UTXO that the rest of the world still accepts","Tax a sale it can see","Seize coins from a custodian it can reach"],"answer":1,"explanation":"Laws bind people and companies in reach of the court. They do not rewrite other people's nodes. Coins on an exchange the state can touch are a different story from coins behind a key it does not have."},{"q":"Free software around Bitcoin Core matters because?","options":["The license sets the supply","A company can patch your node in secret","You can read, build, and refuse to run a change","Miners own the copyright to blocks"],"answer":2,"explanation":"Bitcoin Core is released under the MIT license. Reproducible builds help you check that the binary matches the source. You still decide which version to run."},{"q":"Guix builds in Bitcoin Core exist so that?","options":["Wallets lose their seeds","Users must trust one website's binary","The supply can be raised in the build","Independent builders can reproduce the release"],"answer":3,"explanation":"A reproducible build lets several people start from source and reach the same binary. It does not make the developers infallible. It makes silent swaps harder."},{"q":"Reading a BIP is how a rule change starts, but activation still needs what?","options":["Widespread node and miner behavior, depending on the fork","A blog post alone","An ETF vote","A single maintainer's key"],"answer":0,"explanation":"Anyone can write a proposal. BIP status numbers do not put code on your node. Soft forks need enough enforcement to matter, and hard forks need you to opt in."},{"q":"The MIT license on Bitcoin Core allows what, with almost no conditions?","options":["A patent on the 21 million cap","Reuse of the code, including in other programs","Ownership of the Bitcoin name by one person","A ban on forking the repository"],"answer":1,"explanation":"You can copy the software. You cannot copy the ledger's economic majority by copying the code. A fork of the software that changes consensus is a different network unless users follow it."},{"q":"A pull request merged in Bitcoin Core is not yet your rule until?","options":["An ETF buys it","It is discussed on social media","You run a release that includes it, and it is consensus-relevant only if it changes validation","A miner tweets it"],"answer":2,"explanation":"Most merges are wallet bugs, RPC tweaks, or policy. Consensus changes are rare and documented. Your node enforces the code you actually run."},{"q":"Policy and consensus differ how in one sentence?","options":["Consensus is optional","They are the same word","Policy can create coins","Consensus is what blocks must obey; policy is what your node chooses to relay"],"answer":3,"explanation":"A block that breaks consensus is ignored. A transaction that breaks your policy may still be mined by someone else and then be in a valid block you must accept. OP_RETURN size is the textbook example."},{"q":"Standardness rules exist mainly to do what?","options":["Limit denial-of-service and surprise scripts in the public relay network","Raise the supply","Ban Lightning","Freeze dusty coins you already have"],"answer":0,"explanation":"Nodes decline to relay some odd but consensus-valid transactions. Miners can still include them. Wallet authors usually stay inside standardness so payments propagate."},{"q":"The anniversary people call Bitcoin Pizza Day is which date?","options":["October 31, the whitepaper","May 22, the day the pizzas were delivered in 2010","January 3, the genesis block","April 20, every halving"],"answer":1,"explanation":"Laszlo posted the offer on May 18, 2010. The two pizzas showed up on May 22, which is the day the community marks. The 10,000 BTC figure is the offer, not a price target."},{"q":"A full node does not need to be a miner. Why does that matter?","options":["Wallets must mine to receive","Only miners can reject a fake coin","Validation, not hash rate, decides which rules you follow","Pools set your balance"],"answer":2,"explanation":"Miners propose blocks. Nodes accept or reject them. A world of miners and no verifying users would not be the same system. You can verify on a small computer."},{"q":"What is the smallest unit the consensus rules actually count?","options":["The vbyte","The bit, which is a display name only","The dollar","The satoshi, one hundred-millionth of a bitcoin"],"answer":3,"explanation":"Amounts in transactions are integer sats. \"Bits\" (100 sats) and BTC are ways wallets display the same integer. Display units do not change the UTXO."},{"q":"One bit, in the display convention some wallets offer, equals what?","options":["100 satoshis","1 satoshi","1 bitcoin","1 vbyte"],"answer":0,"explanation":"A microbitcoin is also 100 sats, and some interfaces call that a bit. So 1 BTC is 1,000,000 bits. This is presentation, not a second supply."},{"q":"100 sats is which fraction of a bitcoin?","options":["One hundred bitcoin","One millionth of one bitcoin","The dust consensus ban","A Lightning capacity unit"],"answer":1,"explanation":"100 / 100,000,000 = 0.000001 BTC. It is a normal amount for a tiny Lightning tip. Its dollar value changes and is not a protocol constant."},{"q":"Sending one satoshi on chain is often impractical because?","options":["Miners keep all sats","The protocol forbids odd numbers","Fees and dust policy cost more than the output is worth","Wallets cannot display sats"],"answer":2,"explanation":"A one-sat output is below common dust limits, and the fee to create it can exceed it. Lightning is where tiny amounts actually move. On chain, batch or wait for a real payment."},{"q":"Batching several payments in one transaction saves fees because?","options":["Change disappears","Each output gets a free subsidy","The weight limit does not apply","You pay for one set of inputs to create many outputs"],"answer":3,"explanation":"The expensive part is often the inputs. Payroll and exchange withdrawals use batching for that reason. Receivers still get independent outputs."},{"q":"A coinjoin and a batched payment look similar only if?","options":["You ignore whether the inputs had different owners","They both use OP_CAT","They both are Lightning","They both burn coins"],"answer":0,"explanation":"A batch from one sender has many outputs and usually one owner's inputs. A CoinJoin deliberately mixes owners. Amount patterns can still reveal a lot. Equal outputs are one CoinJoin hint, not proof."},{"q":"PayJoin is a payment and a CoinJoin at the same time in the sense that?","options":["It requires a mixer website","Sender and receiver both contribute inputs to one transfer","It is only for ordinals","It happens off chain"],"answer":1,"explanation":"The receiver pays themselves as part of receiving, which breaks the common-input heuristic. Both parties sign. It is specified in BIP78 and needs wallet support on both ends."},{"q":"Stonewall and other fake-coinjoin patterns try to do what?","options":["Change the fee rules","Legally erase history","Look confusing to a casual chain analyst","Create sats"],"answer":2,"explanation":"Some wallets add extra inputs and change to avoid a simple payment shape. A determined analyst may still cluster you. Privacy is a spectrum, not a switch."},{"q":"Your node is the tool that makes \"don't trust, verify\" literal because?","options":["It sets the price","It calls a miner's API for a yes or no","It stores the seed for you","It checks signatures, supply, and work itself"],"answer":3,"explanation":"A wallet that asks a random server whether you were paid is trusting that server. A node you run applies the rules to the blocks. That is the whole slogan in one machine."},{"q":"The best backup of a bitcoin wallet is tested when?","options":["Before you need it, by a restore that receives a small amount","After the house fire","By emailing the words to yourself","By posting the xprv"],"answer":0,"explanation":"Write the words, restore them on a spare wallet, and send a tiny payment you can see. Then wipe the spare. An untested backup is a story, not a backup."},{"q":"A firmware update on a hardware wallet should be checked how?","options":["By typing the seed into the updater site","Against the vendor's signature, on a clean machine, not from a random link","By posting a photo of the words","By skipping it forever with no plan"],"answer":1,"explanation":"Updates fix real bugs. They are also a moment attackers phish. Use the vendor's documented path, verify the file if the device says to, and never enter the seed into a browser to \"update.\""},{"q":"A phishing site that copies a wallet's look will usually ask for what next?","options":["A block header","Only your public address","The seed phrase or a fake \"restore\"","Your node port"],"answer":2,"explanation":"The page wants the secret. Bookmark the real app, type the URL yourself, and treat urgency as a signal to stop. Hardware signing still helps if the device shows a different address than the page."},{"q":"Sim swap and email takeover matter for bitcoin because?","options":["Miners require a SIM","SHA-256 uses your phone number","Nodes log in with SMS","Exchanges and some wallets use email or SMS for reset"],"answer":3,"explanation":"If a custodian will reset access to whoever holds the email, then the email is part of the key. A personal node does not have that reset. Know which accounts can be socially engineered."},{"q":"Public Wi-Fi is a bad place to type a seed because?","options":["The machine and the network are both untrusted","The protocol broadcasts seeds","Lightning requires public Wi-Fi","Bech32 fails on wireless"],"answer":0,"explanation":"Assume the computer is logging keys. Sign on a hardware device, or do not sign. Viewing a watch-only balance is a different, milder risk than typing words."},{"q":"A paper wallet generated by a website is dangerous when?","options":["You generated it offline from dice and never typed it","The site, or a compromised printer, saw the key","You used a hardware device's own entropy","You only printed an xpub"],"answer":1,"explanation":"Browser generators have stolen funds before. If a machine learned the private key, it is not cold. Prefer a hardware wallet or an offline tool you built, and transfer a test amount first."},{"q":"Sweeping a paper wallet by importing the key into a hot wallet can do what surprise?","options":["It mines a block","It doubles the coins","Later change from a spend may go somewhere you did not back up","It signs the genesis output"],"answer":2,"explanation":"Some sweeps expose the whole key to a phone and then send change to a new address inside that phone. If you only saved the paper, the change is not on the paper. Know where change goes before you spend."},{"q":"The right way to retire a dusty or poisoned UTXO is often what?","options":["RBF the genesis block","Send the seed to support","Post the address online for help","Leave it, or spend it in a CoinJoin or a donation you chose"],"answer":3,"explanation":"A dusting output that you never touch does little. Spending it can link your other coins. If you must move it, do it on purpose, not by letting a wallet grab every UTXO automatically."},{"q":"When a wallet says \"consolidate all,\" you should ask what?","options":["Whether linking those coins is acceptable, and what the fee is","Whether it raises the supply","Whether the SEC must co-sign","Whether it changes your seed words"],"answer":0,"explanation":"Consolidation is a real tool when fees are low and the coins share a history already. It is a privacy loss when the coins came from unrelated people. Read the input list."},{"q":"A node on a home connection can limit bandwidth by what?","options":["Turning off validation","Capping peers, using prune mode, and serving blocks less aggressively","Mining only empty blocks","Using a custodial API"],"answer":1,"explanation":"Bitcoin Core has prune, dbcache, and connection settings. You do not need to upload the whole chain to be safe. You do need to download and check it once."},{"q":"Tor or a VPN for your node hides what, and not what?","options":["The fact that you hold keys in a safe","Your transaction graph inside the blocks","Your home IP from peers, not your on-chain addresses","A seed in an email"],"answer":2,"explanation":"Network privacy and chain privacy are different. A node over Tor is harder to map to your house. The payments you make still appear in the public ledger under their addresses."},{"q":"Running Bitcoin Core over Tor is a documented option that does what?","options":["Required since 2009","Makes every payment a CoinJoin","Disables fees","Listens and connects as a Tor hidden service if you set it up"],"answer":3,"explanation":"Core can be a Tor onion service so peers reach you without a clearnet address. It is optional. It does not mix your coins."},{"q":"A mempool.space page or any explorer is what kind of tool?","options":["Someone else's view of the chain, convenient and trust-based","Your own validation","A hardware wallet","A seed backup"],"answer":0,"explanation":"Explorers are wonderful for learning a txid. For money you care about, confirm the same payment on your node. An explorer can be wrong, hacked, or logging the addresses you search."},{"q":"Searching your address on a random website leaks what?","options":["Your private key, automatically","That you care about that address, to the site and its host","The mining nonce","A BIP39 word"],"answer":1,"explanation":"The lookup itself is metadata. Use your own node, or accept that the explorer learned the query. Do not paste a seed into a \"balance checker.\""},{"q":"A txid changes if what changes?","options":["The explorer's CSS","The dollar price","Any byte of the signed transaction that the txid covers","Your node's prune setting"],"answer":2,"explanation":"SegWit txids exclude witness data, which fixed a malleability issue for Lightning. A legacy txid could change if a signature encoding changed. Either way, you track the id your wallet shows after broadcast."},{"q":"Transaction malleability, before SegWit, made which Lightning problem worse?","options":["Seeds rotated daily","The supply could be edited","Fees became illegal","A parent txid could change, breaking a pre-signed child that pointed at it"],"answer":3,"explanation":"If you pre-sign a spend of a funding transaction and then the funding txid changes, your pre-signed spend is garbage. SegWit's txid commitment was a key step for reliable channels."},{"q":"The witness discount was partly adopted to do what?","options":["Make fixing malleability and adding signature data less painful in fees","Punish all payments","Remove scripts","Ban hardware wallets"],"answer":0,"explanation":"Putting signatures in the witness both solved malleability for those outputs and priced those bytes lower. That was an explicit engineering tradeoff during the block-size fight, not an accident."},{"q":"A payment channel factory, in the research sense, tries to do what?","options":["Print channel capacity","Let many channels share one on-chain UTXO","Replace Schnorr","End fees"],"answer":1,"explanation":"Factories and related covenant ideas would open lots of channels with less block space. They are not how most users open channels today. CTV and similar proposals are discussed for this and are not activated."},{"q":"BIP119, CheckTemplateVerify, would let a script require what?","options":["That the supply inflate","That a miner include a fee of zero","That the spending transaction match a committed template","That an oracle take custody"],"answer":2,"explanation":"Jeremy Rubin's CTV commits to a template hash so a coin can only be spent in pre-defined ways. Uses people discuss include vaults and congestion-control trees. It is a proposal, not an active rule."},{"q":"Why did some bitcoin developers resist a quick CTV activation?","options":["It was an ETF rule","CTV already shipped in 2009","It removed proof of work","They worried covenants could be used in ways that are hard to undo"],"answer":3,"explanation":"Covenants restrict future spends. That can build vaults, and it can also build constructions critics dislike. The argument is about caution and use cases, not about whether the opcode's name is real."},{"q":"A vault design, in plain language, delays a spend so that?","options":["You can claw the coins back to a safer key if a thief rushes","The thief gets a bonus","Miners must co-sign","The coins become an NFT"],"answer":0,"explanation":"The usual picture is a hot key that can only start a withdrawal, plus a delay, plus a colder key that can abort to a rescue path. CTV and other covenant ideas are one way to build that. Multisig with a timelock is the tool people can use now."},{"q":"OP_CHECKLOCKTIMEVERIFY was specified in which BIP, and what does it do?","options":["BIP9; it sets the logo","BIP65; it locks an output until a height or time","BIP39; it picks words","BIP340; it is Schnorr"],"answer":1,"explanation":"CLTV makes an output unspendable until the lock expires. Lightning HTLCs use timelocks so a stuck payment can be reclaimed. The opcode has been active for years."},{"q":"BIP68 and BIP112 relative timelocks let a script say what?","options":["The address expires and the coins vanish","The fee must be zero","This input cannot be spent until N blocks or seconds after its parent confirms","The miner chooses the recipient"],"answer":2,"explanation":"Relative locks are how Lightning commitments create a dispute window. CSV is the opcode. They are measured from the parent confirmation, not from the genesis block."},{"q":"A force-close of a Lightning channel publishes what?","options":["An ETF basket","Your seed","A brand-new bitcoin","The latest commitment the closing party has, which the other side can punish if it is stale"],"answer":3,"explanation":"The chain sees a settlement transaction. If you cheat with an old balance, the counterparty's justice transaction can take the funds during the delay. That is why backups of Lightning state matter more than a single seed in some wallets."},{"q":"Static channel backups in some Lightning wallets restore what, and not what?","options":["Enough to ask peers to close, not a promise of every in-flight payment","The entire history with no peer online","Your on-chain seed only, with channels implied","A miner's template"],"answer":0,"explanation":"An SCB lets the wallet contact the peer and settle. If the peer is gone and you have no state, funds can be stuck until timeouts. Read what your implementation actually backs up before you put rent money in a channel."},{"q":"On-chain fees and Lightning routing fees are paid to whom?","options":["The SEC, in both cases","Miners for block space, and routing nodes for forwarding","Only the sender's bank","A burn address required by consensus"],"answer":1,"explanation":"An on-chain fee is input minus output. A Lightning hop takes a small fee set by that node. Neither fee is a tax baked into the protocol, and both can be zero only if someone is willing to do the work free."},{"q":"A routing node earns fees only if?","options":["It holds an ETF","It mines a mainchain block","Payments actually flow through channels it has balanced","It stores other people's seeds"],"answer":2,"explanation":"You need inbound and outbound liquidity on a path people use. Many hobby nodes earn very little. That is fine if your goal is to pay, not to run a business."},{"q":"Pick the accurate statement about bitcoin's supply and its price.","options":["Neither can be known even roughly","Both are fixed in the whitepaper","The price is fixed and the supply is a vote","The supply schedule is fixed in the software; the price is not"],"answer":3,"explanation":"Anyone can audit how many coins the subsidy has created. What the next buyer will pay is a market. Quizzes here will not tell you that number in advance."},{"q":"A \"number go up\" joke is honest when it admits what?","options":["Past appreciation is not a schedule the software enforces","The code raises the price every block","Miners set a peg","ETFs repealed volatility"],"answer":0,"explanation":"People joke about NGU because the long chart has risen through violent drawdowns. The joke is not a model. You can lose money. Nothing here is advice to buy."},{"q":"The largest historical drawdowns included which 2011 move?","options":["A one-day drop in July from $32 to $2 that finished the bear","From about $32 in June 2011 to about $2 in November 2011","A protocol bug that deleted coins","An ETF liquidation"],"answer":1,"explanation":"The 2011 bubble peaked in June and the famous low was months later, in November, down about 94 percent. It was not a one-week July event. Later drawdowns were also severe. History is not a floor."},{"q":"Volatility is the tradeoff bitcoin users point at when they say what?","options":["Nodes smooth the price","Volatility is banned after 21 million coins exist","A fixed supply cannot also promise a stable dollar price","The halving sets a peg"],"answer":2,"explanation":"If issuance cannot expand to meet selling, the price moves instead. Stablecoins and ETFs are attempts to wrap exposure. They add counterparties. The base asset stays volatile."},{"q":"A stablecoin such as USDT is a claim on whom?","options":["The genesis address","A miner's coinbase","An OP_RETURN that cannot be spent","The issuer's reserves and legal promises, not on Bitcoin's subsidy"],"answer":3,"explanation":"Tether and similar tokens are liabilities of their issuers. After 2022 Tether said reserves were mostly US Treasury bills, not commercial paper. They can freeze addresses under their own rules. They are not bitcoin."},{"q":"Putting a stablecoin on a bitcoin sidechain or Lightning still leaves what risk?","options":["The issuer can fail or censor, even if the transport is bitcoin","The satoshi cap applies to the token","SHA-256 backs the dollar","The IMF redeems it"],"answer":0,"explanation":"The rail can be decentralized while the asset is not. Know which one you hold. Bitcoin the asset has no issuer. A token that says it is worth a dollar has a balance sheet."},{"q":"Liquid, the Blockstream sidechain, trades bitcoin how?","options":["With no peg and no custodian","Inside a federation of functionaries who hold the backing","As a hard fork of the supply","As an ETF share"],"answer":1,"explanation":"You swap mainchain bitcoin for L-BTC by pegging in. A federation controls the peg. It is faster and more private in some ways, and it is not the same as holding the UTXO yourself on the main chain."},{"q":"A federated sidechain peg fails closed or open depending on what?","options":["The user's seed checksum","The 10-minute target","Whether the functionaries sign, which is a trust assumption","The color of the logo"],"answer":2,"explanation":"If enough functionaries go offline or collude, the peg can stall or, in the worst design, be stolen. Read the threshold. Do not describe a federation as \"just bitcoin\" without that sentence."},{"q":"Drivechains, a proposal, would peg sidechains using whom?","options":["The SEC","A single company key","No one, because the coins are burned","Miners who vote on withdrawals, with a long delay"],"answer":3,"explanation":"Paul Sztorc's drivechain idea lets miners escrow a withdrawal over many blocks so users can react. It is not activated. Critics worry about miner power. It is a proposal to study, not a wallet you can open today."},{"q":"Extension blocks, an old scaling idea, would have done what?","options":["Put extra data in a parallel block that old nodes do not fully see","Raised the supply","Removed signatures","Banned Lightning"],"answer":0,"explanation":"The idea was to extend capacity while trying to keep old nodes on a compatible chain. It was not adopted. SegWit and Lightning were the path that shipped. You should not describe extension blocks as a live feature."},{"q":"The Lightning Network does not create bitcoin. Capacity comes from where?","options":["A second subsidy in the BOLTs","On-chain UTXOs locked into channels","ETF shares","Donations from the genesis address"],"answer":1,"explanation":"Every sat in a channel was mined or bought and then locked. Routing rearranges claims on that capacity. When channels close, the same sats settle on chain, minus fees."},{"q":"A channel that is force-closed during a fee spike can be painful because?","options":["The chain ignores closes","Lightning fees are always zero","The settlement transaction still has to buy block space","Watchtowers pay the fee by rule"],"answer":2,"explanation":"Off-chain payments are cheap until you need the chain. Anchor outputs and fee bumping exist for that moment. Size your channels knowing that exit has a cost."},{"q":"Receiving a Lightning payment generally requires what?","options":["An ETF","A confirmed on-chain output for every tip","A miner friend","Liquidity on your side of some path, or a service that provides it"],"answer":3,"explanation":"If you have no inbound liquidity, the payment cannot land. Apps like Phoenix obtain it for you and charge a fee. Custodial wallets hide the problem because they receive on their own channels."},{"q":"A Lightning address that looks like an email is usually what?","options":["A server that hands out invoices, often run by a custodian or your own node","A BIP39 word","A block header","An OP_RETURN"],"answer":0,"explanation":"LNURL and Lightning addresses are convenience protocols over HTTPS. Who runs the server can see metadata and, if they are custodial, can hold the funds. Self-hosted addresses exist and are a different setup."},{"q":"Boltz and similar swap services are useful when?","options":["You want them to keep your seed","You want to move between on-chain bitcoin and Lightning without running the whole swap yourself","You want a price peg","You want to mint ordinals only"],"answer":1,"explanation":"A submarine swap locks coins so the swap can be atomic if the software is honest and the timelocks fire. You still review the service. \"Atomic\" does not mean \"no fees\" or \"no bugs.\""},{"q":"Alex Bosworth's Lightning Loop popularized submarine swaps at which company?","options":["Tether","The Federal Reserve","Lightning Labs","A pizza shop"],"answer":2,"explanation":"Loop In and Loop Out move value between a Lightning balance and an on-chain output using submarine swaps. Loop was built at Lightning Labs."},{"q":"An atomic swap across chains needs what at minimum?","options":["An ETF authorized participant","A shared CEO","The same block time","Hash or signature locks and refund timelocks on both chains"],"answer":3,"explanation":"The classic HTLC swap lets each side refund if the other disappears. It does not need a custodian in the happy design. It does need both chains to support the script, and it can still leak the preimage."},{"q":"A custodial swap is different because?","options":["You send coins and trust the site to send the other asset","The protocol guarantees a refund in the mempool","Miners arbitrate the website","Your node co-signs"],"answer":0,"explanation":"If you deposit to a website's address, you are a creditor until they pay you. Read the URL twice. Phishing clones of swap sites are common."},{"q":"What should you do with a seed a website says you \"won\"?","options":["Import it quickly before it expires","Ignore it. A seed someone else generated is a trap","Post it so friends can share","Use it as a passphrase only"],"answer":1,"explanation":"If a stranger knows the words, they know the keys. Giveaway seeds exist to collect the fee you deposit. Generate entropy on a machine you control."},{"q":"A wallet backup written in a photo of a whiteboard fails when?","options":["BIP39 rejects handwriting","Steel would have been heavier","The photo syncs to a cloud account you forgot","Nodes see the photo"],"answer":2,"explanation":"Phone cameras upload themselves. A picture of a seed is a copy. If you must photograph one for a momentary transfer, treat that phone as hot and delete the image from every backup, then assume you failed and move the coins."},{"q":"Cloud-stored password managers and seeds mix how badly?","options":["A passphrase is unnecessary there","They are safer than steel by consensus","Core encrypts your Google Drive","Whoever breaches the vendor or your email can take the coins"],"answer":3,"explanation":"A password manager can store an xpub or a descriptor. Storing the only copy of a seed there puts your savings at the vendor's security. Prefer offline metal for the long-term secret."},{"q":"The phrase \"not your keys, not your coins\" came into wide use after what lesson?","options":["Exchange failures, especially the Mt. Gox collapse","The Unicode ₿ addition","The 2024 ETF launch","A line in the 2008 abstract"],"answer":0,"explanation":"Mt. Gox collapsed in 2014 after losing hundreds of thousands of bitcoin to its own systems. Customers learned a website balance is not a UTXO. Later failures, including FTX, repeated the lesson."},{"q":"Mt. Gox's name originally referred to what?","options":["A Japanese government mint","Magic: The Gathering Online Exchange, a card site turned into a bitcoin exchange","Satoshi's mining pool","A hardware wallet"],"answer":1,"explanation":"Jed McCaleb's card-trading site was repurposed for bitcoin around 2010 and later sold to Mark Karpelès. The name is a joke about the card game, not a monetary term."},{"q":"Mark Karpelès was convicted in Japan of what, in the Mt. Gox case?","options":["Writing the whitepaper","Stealing the genesis block","Falsifying data; the embezzlement charge did not stick","Running a 51 percent attack"],"answer":2,"explanation":"A Tokyo court convicted him of manipulating electronic records. Embezzlement charges were dismissed. The missing coins were a mix of long-running theft and bad books, not a break of SHA-256."},{"q":"Mt. Gox creditor repayments that began in 2024 were notable because?","options":["No coins were ever found","Everyone was paid in 2015 at the old price","The chain was rolled back","Creditors waited about a decade and were paid in bitcoin worth more dollars than the 2014 claim"],"answer":3,"explanation":"The exchange reported about 850,000 BTC missing and later found about 200,000 in old wallets. Civil repayments started in 2024. The protocol itself had not been rewritten."},{"q":"A exchange proof-of-liabilities is harder than proof-of-reserves because?","options":["Customers and the firm may not publish a complete, private list of what is owed","Miners refuse to sign","UTXOs are not real","The genesis block must be included"],"answer":0,"explanation":"You can show coins with a signature. Showing you owe exactly those coins to the users, and nothing more to insiders, needs a liability statement users can check. Few firms do both in a strong way."},{"q":"When an exchange freezes withdrawals, on-chain bitcoin outside it does what?","options":["Also freezes, by law of the protocol","Keeps moving under the same rules","Reverts to the exchange","Loses six confirmations"],"answer":1,"explanation":"The freeze is the company's database. Coins in your wallet do not consult it. Coins in their wallet do whatever they, a hacker, or a court do with the keys."},{"q":"A court can order a custodian to send coins. A court cannot, by the order alone, do what?","options":["Garnish a bank account it can see","Arrest a person in its jurisdiction","Make your self-custodied UTXO move without a signature","Tell an exchange to freeze a login"],"answer":2,"explanation":"Jurisdiction is about people and institutions. Cryptography does not repeal police powers over things they can reach. It raises the cost of reaching a key that was never online."},{"q":"Privacy is not the same as hiding from a lawful process you are actually in. The accurate claim is?","options":["KYC is a consensus rule","Bitcoin is invisible to all courts","Chain analysis does not exist","Self-custody removes casual surveillance, not every legal tool"],"answer":3,"explanation":"Companies with KYC files will hand them over. The chain is public. A careful user leaks less. Nobody should expect a magic cloak, and this is not legal advice."},{"q":"Chain analysis clusters addresses using heuristics such as what?","options":["Common-input ownership and change detection","Reading the seed from the block","A backdoor in SHA-256","The miner's passport"],"answer":0,"explanation":"If several inputs are signed together, analysts guess one owner. Change-detection guesses which output is yours. PayJoin and CoinJoin exist to weaken those guesses. They are guesses, not proofs, but they are often right."},{"q":"KYC means what at a regulated exchange?","options":["The chain records your legal name","They collect your identity before you trade","Miners vote on your account","Your node requires a passport"],"answer":1,"explanation":"Know-your-customer is a compliance process at a business. Bitcoin addresses do not contain names. The link is in the company's file and in how you move coins after you withdraw."},{"q":"Non-KYC coins are not a separate asset. The phrase means what?","options":["Coins that cannot be traced ever","A privacy altcoin","Coins acquired without an identity check at a company","Coins miners were paid under a special rule"],"answer":2,"explanation":"A coin has no KYC bit. The label describes the buyer's relationship to an exchange. Those coins are still on the same ledger, and later spending can still be analyzed."},{"q":"Buying peer to peer, in person, has which obvious risk?","options":["A change to the supply","A protocol fee of 10 percent","Automatic reporting to your node","Personal safety and counterfeit payments, plus legal rules where you live"],"answer":3,"explanation":"Meet in a sane way, understand your local law, and do not flash wealth. Peer-to-peer trade is how bitcoin moved before ETFs. It is not advice to evade taxes or to take bad risks."},{"q":"A bitcoin ATM's premium and camera do what?","options":["Charge you more and may record you, while still sending a real on-chain payment","Mint a private bitcoin","Avoid all fees by law","Connect you to the genesis address"],"answer":0,"explanation":"The machine is a vending counterparty. Read the rate, the camera policy, and the receipt. Send to an address you control. The convenience is not a discount."},{"q":"Mining at home on a Bitaxe is rational for which goal?","options":["Matching a pool's revenue per watt in a serious business","Learning, heating a room a little, and a tiny chance of a solo block","A guaranteed sat per day","Filing as an ETF"],"answer":1,"explanation":"Open-source boards hash at a hobby scale. A solo block is a lottery ticket against the whole network. Do the electricity math. People have solo-mined with small machines; that is luck, not a plan."},{"q":"Pool payout schemes such as FPPS are contracts with whom?","options":["Your hardware wallet","The Bitcoin protocol, which owes you a salary","The pool, which may pay you even when it finds no block, according to its terms","The difficulty adjustment"],"answer":2,"explanation":"Full pay per share means the pool takes variance risk and charges a fee. If the pool operator disappears, the contract disappears. Read the fee and the custody of unpaid balance."},{"q":"A pool can censor transactions in Stratum v1 more easily because?","options":["Nodes refuse pool blocks","The miner must include every tx by consensus","SHA-256 rejects censored blocks","The pool builds the block template the miner hashes"],"answer":3,"explanation":"If you only hash a header the pool sent, you are working on the pool's choice of transactions. Stratum V2 job negotiation lets the miner supply the template. That is the decentralization argument for upgrading."},{"q":"Which statement about empty blocks is fair?","options":["They are valid, waste space, and better protocols try to make them rare","They are invalid after 2017","They pay a double subsidy","They are required every 2016 blocks"],"answer":0,"explanation":"A block with only a coinbase is legal. It confirms nothing else. Pools that start hashing before transactions are ready produce more of them. It is a coordination issue, not a second rule set."},{"q":"ASICBoost is an optimization that does what?","options":["Breaks SHA-256 outright","Finds shortcuts in searching the header, in overt or covert forms","Doubles the supply","Disables SegWit by physics"],"answer":1,"explanation":"Overt ASICBoost uses the version bits in a visible way. Covert forms were discussed as a reason some miners disliked SegWit, because SegWit changed how covert boosting worked. The network still runs SHA-256."},{"q":"A miner's breakeven depends on power price, efficiency, and what else?","options":["The color of the machine","A fixed protocol wage","The bitcoin price and the fee environment, which move","An ETF management fee only"],"answer":2,"explanation":"Large miners often chase a few cents per kilowatt-hour. Home power is usually more expensive. Nobody's breakeven is a constant you should memorize as a fact for all years."},{"q":"Energy use secures bitcoin because an attacker must do what?","options":["Buy an ETF share","Bribe a single admin","Edit a database row","Spend real electricity to rewrite work honest miners already published"],"answer":3,"explanation":"Proof of work is costly to produce and cheap to check. That asymmetry is the design. Whether society wants to spend that energy is a political argument; the security claim is about the cost of a rewrite."},{"q":"Stranded energy means power that is what?","options":["Hard to sell because it is remote, curtailed, or wasted","Illegal to use","Only coal","Free of physics"],"answer":0,"explanation":"A gas flare, a curtailed wind farm, or a hydro plant far from a city may have energy with no buyer. Miners can sit at the source. That does not make every mining company green, and it does not make the energy free."},{"q":"Heat reuse from miners is real when?","options":["The protocol pays a heat credit","The heater was going to run anyway, and the miner replaces it","SHA-256 becomes cold","The coins are burned for warmth"],"answer":1,"explanation":"A miner is an electric heater that also hashes. If you need the heat, the electricity would have been used by a dumb heater. If you do not need the heat, it is just a cost. Some projects sell mining space heaters on that basis."},{"q":"Comparing bitcoin's energy to a country's grid is misleading when the speaker forgets what?","options":["That the comparison is a consensus rule","That miners use no power","What the energy buys, and that other money systems use energy too","That terawatt-hours are not real"],"answer":2,"explanation":"A serious comparison includes the banking system, ATMs, branches, and the military that back fiat, which are hard to measure. It also includes bitcoin's actual mix and the fact that miners shut off when power is scarce. Pick sources, and date them."},{"q":"A node that rejects a block for breaking the supply rule is doing what?","options":["Waiting for an ETF vote","Censoring a legal payment","Forking to a new coin by accident","Enforcing the cap, even if a miner with hash power disagrees"],"answer":3,"explanation":"If a block pays an extra subsidy, your node ignores it and waits for an honest one. That is the cap. Hash power alone does not define bitcoin for users who verify."},{"q":"The halving is called disinflationary because?","options":["New coins are still issued, but the rate falls","The supply shrinks on a schedule","All coins are burned every four years","Prices must fall in dollars"],"answer":0,"explanation":"Disinflation means the flow of new money slows. Deflation of the stock would require coins to be destroyed faster than they are created. Lost keys can do that in practice, but it is not scheduled."},{"q":"After the last satoshi of subsidy, miners are paid by whom?","options":["A tail emission hardcoded to 1 BTC","Fee-paying users, if users still want block space","The IMF","Automatic ETF yields"],"answer":1,"explanation":"The software does not add a tail emission. Fees are the remaining reward. Whether that market will be deep enough in 2140 is the security-budget argument, and it is not settled."},{"q":"A fee market means users do what when blocks are full?","options":["Vote to double the block","Receive a refund from the genesis address","Bid with fees, and low bids wait","Pay a posted price from Core"],"answer":2,"explanation":"There is no protocol-set fee. Wallets estimate from recent blocks. You can pay more to hurry or less to wait. That is the market, and it is not advice about what fee to choose today."},{"q":"Replace-by-fee is a courtesy to whom?","options":["The recipient's seed","A merchant who already shipped on zero conf","An attacker who wants free replacements","The spender who underpriced, and the miner who wants the higher fee"],"answer":3,"explanation":"RBF lets the owner of the inputs try again. A merchant who treated the first broadcast as final can be disappointed. For a donation or a self-transfer, RBF is purely helpful."},{"q":"CPFP is a courtesy the receiver can use when?","options":["They can spend the unconfirmed output they were just paid","They know the sender's seed","The transaction is confirmed","The output is OP_RETURN"],"answer":0,"explanation":"You attach a child that pays a generous fee. Miners who take the package get both fees. If the output is not yours yet, you cannot do this."},{"q":"A transaction stuck for days is usually stuck because?","options":["The seed expired","Its fee is below what miners are including, not because it was deleted from history","The address reused a nonce","Core v30 rejected all fees"],"answer":1,"explanation":"It sits in mempools that still want it, or it has been dropped and must be rebroadcast. Bump the fee, spend a child, or wait. Do not \"cancel\" it by sending your seed to a helper."},{"q":"Dropped from one node's mempool, a transaction can still confirm if?","options":["OP_RETURN ate it","The txid was burned","Another miner has it, or you rebroadcast it","The halving deleted the mempool"],"answer":2,"explanation":"Mempools are local. A restart, a full memory pool, or a policy difference can evict a tx. Keep the signed transaction and broadcast it again. Until it is confirmed or replaced, the inputs are still yours."},{"q":"A double spend of an unconfirmed transaction is a race. A double spend of a confirmed one is what?","options":["How Lightning refunds work","A menu item in every wallet","Free after 10 minutes","An attempt to reorg, which the attacker must outwork"],"answer":3,"explanation":"Once a transaction is in a block with work on top, replacing it means mining a heavier competing chain. That is the 51 percent problem, not a button labeled undo."},{"q":"Your wallet's \"pending\" label should be believed over your node when?","options":["Never, if they disagree; the node is checking the chain","Always, because phones are newer","Only if the app has a green icon","When an explorer agrees with the ad"],"answer":0,"explanation":"The phone may be looking at a server. The node is applying the rules to blocks it validated. If both are yours and they disagree, wait and look at the actual txid rather than the icon."},{"q":"A reorg of one or two blocks happens how often, relative to a deep reorg?","options":["Every block reorgs","Short reorgs happen; deep ones are rare and expensive","Deep reorgs happen daily by design","Reorgs are impossible after SegWit"],"answer":1,"explanation":"Two miners can find a block at nearly the same time. One chain loses, and those transactions return to mempools. A reorg of many blocks would require sustaining more work than the honest chain. It is not a daily event."},{"q":"Orphan, or stale, blocks are what?","options":["The genesis block","Blocks with bad signatures that nodes store forever","Valid blocks that lost the race to another block at the same height","Empty Lightning channels"],"answer":2,"explanation":"The losing block is discarded by nodes that saw the other chain first and then saw more work. Its coinbase cannot be spent. The transactions usually reappear in the winning chain if they did not conflict."},{"q":"The genesis block's extra mystery is that it is hardcoded how?","options":["It contains every later txid","Miners re-mine it every difficulty epoch","It has no timestamp","Clients ship its hash as the root they agree to start from"],"answer":3,"explanation":"The software trusts the genesis hash as the starting point of the chain. You can see the headline in its coinbase. You do not re-mine it. Every full node agrees on that anchor."},{"q":"Changing the genesis block in your private build does what?","options":["Starts a new network nobody else follows, unless they adopt your build","Rewrites everyone else's ledger","Steals Satoshi's coins","Is the defined soft-fork method"],"answer":0,"explanation":"Consensus is an agreement among people running compatible software. A private genesis is a toy chain. It does not move mainnet coins."},{"q":"A signet or regtest coin has what value on mainnet?","options":["One-to-one, by a BIP","None. It will not be accepted as bitcoin","The same txid space, so it collides","It becomes real after six blocks"],"answer":1,"explanation":"Test coins exist so developers can fail safely. An address on the wrong network will not pay your rent. Check the human-readable prefix: bc versus tb or bcrt."},{"q":"Sending mainnet bitcoin to a testnet address you copied by mistake does what?","options":["It becomes a Lightning payment","It converts automatically","The checksum and prefix usually stop you; if you bypass them you could burn it","It claims an ETF share"],"answer":2,"explanation":"Bech32 includes the network in the human-readable part, so wallets refuse a cross-network send. Raw scripts are less forgiving. Do not bypass a warning you do not understand."},{"q":"A burn address that is a well-known OP_RETURN is different from a vanity address nobody has the key for, because?","options":["OP_RETURN pays a salary","Both are always recoverable by Core","Vanity addresses are consensus-burned","OP_RETURN cannot be spent even if a key appears; a vanity address could be spent by whoever generated it"],"answer":3,"explanation":"If someone generated a vanity address, they might have kept the key, or not. You cannot tell from the address. OP_RETURN has no spend path. Use the right tool if you truly mean to destroy coins."},{"q":"Proof of burn, in general, means what?","options":["Showing you destroyed coins, usually to bootstrap another system","Mining with less energy","A Core command to delete a UTXO","An ETF redemption"],"answer":0,"explanation":"People have burned bitcoin to issue tokens on other systems or to make a public point. The destroyed sats do not come back. Do not burn coins because a website promised a bonus."},{"q":"A website that says \"burn 0.01 BTC to mint a reward\" should be treated as what?","options":["A BIP","Hostile until you can verify the mechanism yourself, which you usually cannot","A miner rebate","A tax form"],"answer":1,"explanation":"The chain will happily destroy coins you send to a burn script. It will not enforce the website's promise. Assume the promise is false."},{"q":"The first-ever bitcoin price feed was an electricity calculation, not what?","options":["From 2009","A real published number","A traded market with order books and a dollar bid","Related to mining"],"answer":2,"explanation":"New Liberty Standard's October 5, 2009 post was a cost-of-production quote, about $0.00076. Exchange markets came later. Do not cite it as a ticker price from a brokerage."},{"q":"Mt. Gox in 2013 processed a huge share of trades. The lesson people drew was what?","options":["Pizza Day was a myth","The protocol needed a CEO","Proof of work had failed","One company's database had become a single point of failure"],"answer":3,"explanation":"A large fraction of dollar trades went through one site. When its books were hollow, the price and a lot of customers suffered. The chain kept producing blocks the whole time."},{"q":"The phrase \"honeybadger of money\" and the phrase \"tick tock next block\" belong in which drawer?","options":["Culture","Consensus","Tax law","The block header"],"answer":0,"explanation":"They motivate people and they date the speaker. They do not validate a signature. Enjoy them, and do not quote them as rules."},{"q":"A good one-sentence description of bitcoin for a newcomer is which?","options":["A stock that pays a dividend set by miners","Digital money with a fixed supply that you can check yourself","An app that a company can shut off for everyone","A dollar token"],"answer":1,"explanation":"You can add Lightning, privacy, and energy later. The first sentence should not be a price prediction or a promise that shops must accept it."},{"q":"Which follow-up sentence is fair about volatility?","options":["Drawdowns ended in 2020","The protocol floors the price at the last halving","The price can fall a long way; do not put in money you cannot lose","ETFs banned crashes"],"answer":2,"explanation":"Education includes the downside. People have lost fortunes in drawdowns and in hacks and in lost seeds. Nothing in this bank is a solicitation to buy."},{"q":"A newcomer who buys a little and practices a backup learns more than one who does what?","options":["Reads the whitepaper once","Runs a node and writes a seed on metal","Sends a tiny Lightning payment","Memorizes a price target and leaves the coins on a stranger's site"],"answer":3,"explanation":"A small amount you can afford to lose is a textbook. The textbook includes restoring the wallet and sending a payment. A forecast does not teach custody."},{"q":"The archive's health channel connects bitcoin with long-term habits. The fair boundary is?","options":["Personal discipline is on-topic; medical orders are not","Bitcoin Core prescribes a diet","Seed oils are a consensus bug","Fasting changes the subsidy"],"answer":0,"explanation":"Saving, sleep, and not panicking are metaphors people use for low time preference. They are not prescriptions. Polls may ask what you think. Quizzes should not pretend a diet is a BIP."},{"q":"Freedom, in the narrow bitcoin sense used here, means what?","options":["You are exempt from every law where you live","You can pay and verify without asking a gatekeeper who can say no","Your coins are invisible","Merchants must accept you"],"answer":1,"explanation":"Permissionless is about the protocol not having an account department. Local law still applies to people. The interesting fact is that the ledger does not check a passport before accepting a valid signature."},{"q":"Self-reliance around money most resembles which other practice?","options":["Letting a feed set your balance","Outsourcing every backup to one vendor","Keeping a copy of the records instead of trusting a clerk","Sharing your seed with the family group chat"],"answer":2,"explanation":"A node is a copy of the ledger you check. A seed backup is a copy of the key you store. Both fail if you make only one sloppy copy or if you hand the original to a chat app."},{"q":"A family that shares one seed in a group chat has done what?","options":["Improved privacy","Created a safe 3-of-5 multisig","Complied with a BIP","Given every member, and the chat vendor, the ability to take the coins"],"answer":3,"explanation":"Use multisig or separate gifts if several people should have access. A chat log is a backup you do not control. Assume it will leak."},{"q":"Teaching a child with a small wallet is sound when?","options":["The amount is tiny, the seed is a practice one, and an adult understands the real backup","The child posts the words for a school project","The only copy is a screenshot","The wallet is an exchange login they do not control and also call \"theirs\""],"answer":0,"explanation":"Practice nets and tiny balances exist so mistakes are cheap. Tell the truth about who holds the key. Do not put a life-changing amount in a demo."},{"q":"A bitcoiner's \"runway\" of savings is analogous to what, without being medical advice?","options":["A guaranteed return","Food in the pantry and skills that last, so a shock does not force a bad sale","A government pension baked into the chain","A reason to skip sleep forever"],"answer":1,"explanation":"People who think in long time preference talk about reserves: coins, calories, and competence. The analogy is cultural. It is not a claim that bitcoin replaces food or a doctor."},{"q":"Which pair is a fair \"sound money and sound habits\" statement?","options":["Miners validate your sleep","The chain tracks your diet","Fix the leak in the budget, and do not store the seed in the cloud","A halving is a meal plan"],"answer":2,"explanation":"The useful overlap is responsibility for future-you. The useless overlap is pretending health fads are protocol facts. Keep those drawers separate."},{"q":"Eric Hughes wrote that cypherpunks write code because privacy will not be delivered by whom?","options":["A full node","A proof-of-work puzzle","A hardware wallet","Governments, corporations, or other large, faceless organizations"],"answer":3,"explanation":"Eric Hughes, A Cypherpunk's Manifesto (March 9, 1993): \"We cannot expect governments, corporations, or other large, faceless organizations to grant us privacy out of their beneficence.\" Source: https://www.activism.net/cypherpunk/manifesto.html"},{"q":"Tim May's crypto-anarchy picture was about cryptography making which costs high?","options":["The cost of coercing anonymous trade and speech","The cost of running a full node in 2009","The cost of pizza in 2010","The cost of an ETF share"],"answer":0,"explanation":"May wrote in 1988 about anonymous networks raising the cost of control. Bitcoin is one later tool in that tradition, not the manifesto itself."},{"q":"Wei Dai's b-money imagined a ledger enforced by whom?","options":["A central mint run by a company","The participants, using money and reputational or deposit penalties in his sketch","The Federal Reserve","No cryptography at all"],"answer":1,"explanation":"b-money (1998) is a sketch with two variants, not a running network. Satoshi cited it. Bitcoin's actual answer was proof of work plus nodes, which Dai's note did not deploy."},{"q":"Adam Back's Hashcash and bitcoin's mining are related how?","options":["Hashcash had a 21 million cap","They are the same software","Both use a hash puzzle as a cost; bitcoin chains the puzzles into a ledger","Hashcash was a bank"],"answer":2,"explanation":"Hashcash made one message expensive. Bitcoin made a chain of such proofs the clock and the vote. Back did not launch bitcoin, and Satoshi cited him rather than handing him the project."},{"q":"Nick Szabo described smart contracts in the 1990s as what?","options":["A custodial exchange","A token sale","A bitcoin opcode that already existed","Protocols that perform the terms of an agreement"],"answer":3,"explanation":"The phrase \"protocols that perform the terms of an agreement\" is how Szabo described smart contracts in the 1990s. He proposed bit gold in 1998, and the Bit gold essay was posted in December 2005. Bitcoin Script is a limited descendant, not a general courtroom."},{"q":"Hal Finney, early in the cypherpunk era, worked on which widely used privacy tool besides later inventing RPOW?","options":["PGP, as an early contributor","The spot bitcoin ETF","Stratum V2","El Salvador's Chivo wallet"],"answer":0,"explanation":"Finney was a well-known PGP developer before Bitcoin. He then built RPOW in 2004 and was first to receive a bitcoin transfer from Satoshi in 2009."},{"q":"The right attribution for \"code is speech\" in US caselaw is?","options":["A guilty plea by Phil Zimmermann","Bernstein v. United States, not a conviction of Zimmermann","Satoshi's July 2010 forum post","The Mt. Gox judgment"],"answer":1,"explanation":"Bernstein fought export rules on source code and won important rulings in the 1990s. Zimmermann was investigated over PGP and was not convicted. Both stories matter; they are not the same story."},{"q":"Assange's link to early bitcoin is accurate in which version?","options":["He received block 170","He coauthored the whitepaper","He was on the cypherpunks list in the 1990s; WikiLeaks used bitcoin in 2011, after Satoshi said not to","He mined the genesis block"],"answer":2,"explanation":"Assange's 1990s list membership is not the same as being there \"when Satoshi published.\" Satoshi asked WikiLeaks not to adopt bitcoin in December 2010. The organization began accepting it in 2011."},{"q":"A quote belongs in this quiz only when?","options":["It appears on a T-shirt","A meme account paraphrased it","It would be in character for the speaker","You can point at the essay, email, or forum post"],"answer":3,"explanation":"Hughes, May, Dai, Szabo, Back, Finney, Satoshi, and Hanyecz are quoted here only in lines with a known source. Paraphrases are labeled as paraphrases. If a line is fuzzy, it is not here."},{"q":"Satoshi's February 11, 2009 post is the source for which cluster of ideas?","options":["Trust, debasement, and fractional-reserve bubbles","The Lightning spec","The ETF approval","The 2025 reserve order"],"answer":0,"explanation":"Satoshi's February 11, 2009 post on the P2P Foundation forum, \"Bitcoin open source implementation of P2P currency,\" contains the \"root problem\" line, the warning about central banks debasing currency, and the line about banks lending in waves of credit bubbles. Source: https://satoshi.nakamotoinstitute.org/posts/p2pfoundation/1/ . BitcoinTalk opened later, in November 2009."},{"q":"The July 29, 2010 \"I don't have time to try to convince you\" reply shows Satoshi's tone was sometimes what?","options":["A formal SEC filing","Impatient, and still on the forum that year","A resignation from a company he chaired","A tweet from 2017"],"answer":1,"explanation":"On BitcoinTalk, July 29, 2010, Satoshi wrote: \"If you don't believe me or don't get it, I don't have time to try to convince you, sorry.\" The sentence is curt. It is not a full philosophy. By December 2010 he was warning that WikiLeaks attention was dangerous for a young project."},{"q":"The December 11, 2010 hornet's-nest post is best read as what?","options":["An endorsement of a political party","A request that WikiLeaks send him coins","A plea to grow slowly because a sudden political use could crush a young network","A soft-fork proposal"],"answer":2,"explanation":"He wrote that the project needed time to strengthen and that the attention could destroy it at that stage. Bitcoin survived. The post is still the right source for the sentence."},{"q":"Which BIP defines bech32m for witness version 1 and later?","options":["BIP 141","BIP 173","BIP 341","BIP 350"],"answer":3,"explanation":"BIP 350, \"Bech32m format for v1+ witness addresses,\" amends BIP 173 so native witness outputs of version 1 and later, including Taproot, use bech32m. Bech32 stays in use for version 0. Source: https://github.com/bitcoin/bips/blob/master/bip-0350.mediawiki"},{"q":"Laszlo's pizza post is a primary source for the 10,000 BTC figure. The delivery date is known from what?","options":["Follow-up posts showing the pizzas arrived on May 22, 2010","A line in the whitepaper","An ETF prospectus","The genesis coinbase"],"answer":0,"explanation":"The offer and the meal are different timestamps. Pizza Day celebrates the meal. Quote the offer from the May 18 thread and the date from the thread's result, not from a meme that merges them carelessly."},{"q":"Finney's tweet is a primary source of two words. The block explorer is a primary source of what companion fact?","options":["That Finney wrote the whitepaper","Block 170's timestamp on January 12, 2009, and the 10 BTC output","That the tweet moved the coins","That January 11 was the transfer"],"answer":1,"explanation":"Do not merge the tweet day and the transfer day. The tweet \"Running bitcoin\" is 03:33 UTC on January 11, 2009, which was the evening of January 10 in California (https://x.com/halfin/status/1110302988). Block 170 is timestamped January 12, 2009 (UTC), with the 10 BTC output."},{"q":"A careful teacher quotes the genesis coinbase how?","options":["As a Wall Street Journal line","As a paraphrase about bailouts with no date","As the exact Times headline Satoshi typed, including the date 03/Jan/2009","As Hal Finney's tweet"],"answer":2,"explanation":"The bytes are the source. The political reading, that he was commenting on bank rescues, is context. The headline text itself is not in dispute."},{"q":"Which of these is a real, checkable whitepaper sentence?","options":["The block reward is a tax","Bitcoin will be worth a million dollars","Miners must be licensed","We have proposed a system for electronic transactions without relying on trust"],"answer":3,"explanation":"The conclusion contains the trust sentence. It contains no price forecast and no request for a license. If a slide adds those, the slide is editorializing."}]
